INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('acl-aging-caregiver-referrals', 'acl-eldercare-locator-national', 'federal-service-referral', '{"listing.title":"Eldercare Locator — national older-adult and caregiver referral","listing.agency":"Administration for Community Living (ACL), U.S. Department of Health and Human Services","listing.summary":"The Administration for Community Living''s Eldercare Locator connects older adults and their families or caregivers with local services. Search by location; call or text 1-800-677-1116, use online chat, or email EldercareLocator@USAging.org. This is a referral service, not an eligibility program or eligibility result.","listing.applicant_types":["older adults","people with disabilities","caregivers","family members"],"listing.opportunity_url":"https://eldercare.acl.gov/home","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"referral","jurisdiction":{"level":"federal","country_code":"US"},"service_scope":"aging_disability_caregiver_referral","catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"us.acl.aging-referrals","effective_at":null,"retrieved_at":"2026-10-30T01:44:03Z","source_version":"ACL Find Help in Your State or Territory page reviewed 2026-10-30; Eldercare Locator page last modified 2026-03-02.","field_provenance":{"listing.title":{"source_url":"https://eldercare.acl.gov/home","observed_at":"2026-10-30T01:44:03Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://eldercare.acl.gov/home","observed_at":"2026-10-30T01:44:03Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://eldercare.acl.gov/home","observed_at":"2026-10-30T01:44:03Z","extraction_method":"operator_review"},"listing.applicant_types":{"sour