INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('cms-medicare-extra-help-listings', 'medicare-extra-help-listing', 'federal-medicare-program-listing', '{"listing.title":"Extra Help (Medicare Part D Low-Income Subsidy)","listing.agency":"Centers for Medicare & Medicaid Services (CMS); applications are available through the Social Security Administration (SSA), with free assistance from State Health Insurance Assistance Programs (SHIPs)","listing.summary":"Helps people with limited income and resources pay Medicare Part D premiums, deductibles, coinsurance, and other costs. Some people qualify automatically; others can apply through Social Security. Medicare.gov also directs applicants to State Health Insurance Assistance Programs for free application help.","listing.program_url":"https://www.medicare.gov/basics/costs/help/drug-costs","listing.record_kind":"assistance_program","core.geography.country_code":"US"}'::jsonb, '{"need_topics":["medicare_drug_costs","prescription_drug_assistance","low_income_support"],"record_role":"program_listing","jurisdiction":{"level":"national","country_code":"US"},"listing_kind":"assistance_program","catalog_namespace":"programs","criteria_coverage":"partial","beneficiary_classes":["People with Medicare and limited income and resources"],"criteria_program_ids":["medicare-extra-help"]}'::jsonb, '{"publisher":"Centers for Medicare & Medicaid Services","source_id":"cms.medicare-extra-help","source_type":"public_source","content_hash":"984360ec29544eee184bded84d188e82790c1bb237a68d2539f72592eeabb1e5","effective_at":null,"retrieved_at":"2026-11-11T02:14:49.224383+00:00","source_title":"Help with drug costs | Medicare","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","approval_status":"approved","criteria_status":"partial_not_mapped","field_p