INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('cms-medicare-extra-help-published-criteria', 'medicare-extra-help-published-criteria-2026', 'federal-program-criteria-reference', '{"eligibility.program.title":"Extra Help (Medicare Part D Low-Income Subsidy)","eligibility.program.program_id":"medicare-extra-help","eligibility.program.data_origin":"Official CMS Medicare.gov Help with drug costs page freshly read 2026-11-11T02:14:49.224383+00:00; source SHA-256 73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e. Published 2026 income and resource thresholds are references only.","eligibility.program.description":"Helps people with limited income and resources pay Medicare Part D premiums, deductibles, coinsurance, and other costs.","eligibility.program.catalog_version":"cms-extra-help-2026-reviewed-2026-11-11","eligibility.program.published_requirements":[{"source_id":"cms.medicare-extra-help","statement":"For 2026, the published income limit is $23,940 for an individual and $32,460 for a married couple. The published resource limit is $18,090 for an individual and $36,100 for a married couple. Medicare.gov says these limits may go up each year. The page points to separate, higher limits for Alaska and Hawaii; those values are not included in this record.","mapping_status":"not_mapped","requirement_id":"income_and_resource_limits_2026"},{"source_id":"cms.medicare-extra-help","statement":"Medicare.gov says Extra Help is automatic for people with full-benefit Medicaid coverage, state payment of Part B premiums through a Medicare Savings Program, or Supplemental Security Income (SSI) payments from Social Security.","mapping_status":"context_only","requirement_id":"automatic_qualification_pathways"},{"source_id":"cms.medicare-extra-help","statement":"People who do not qualify automatically can apply through Social Security and may receive free application help from SHIP. Medicare.gov says Extra Help is unavailable in Puerto Rico, the U.S. Virgin Islands, Guam, the Northern Mariana Islands, and American Samoa; it points residents to their State Medical Assistance office for other local programs.","mapping_status":"context_only","requirement_id":"application_and_geographic_limits"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"national","country_code":"US"},"effective_period":"2026 published limits","catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_status":"not_mapped"}'::jsonb, '{"publisher":"Centers for Medicare & Medicaid Services","source_id":"cms.medicare-extra-help","source_type":"public_source","content_hash":"5272672905cac86a43e540ceda7b0b924e3c9467e603e6758dd4737df0c204f9","effective_at":null,"retrieved_at":"2026-11-11T02:14:49.224383+00:00","source_title":"Help with drug costs | Medicare","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","approval_status":"approved","criteria_status":"partial_not_mapped","field_provenance":{"eligibility.program.title":{"source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","observed_at":"2026-11-11T02:14:49.224383+00:00","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","observed_at":"2026-11-11T02:14:49.224383+00:00","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","observed_at":"2026-11-11T02:14:49.224383+00:00","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","observed_at":"2026-11-11T02:14:49.224383+00:00","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.medicare.gov/basics/costs/help/drug-