INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('farmers-gov-farm-finance-listings', 'farm-operating-loans', 'federal-farm-finance-listing', '{"listing.title":"Farm Operating Loans","listing.agency":"Farm Service Agency (FSA), USDA","listing.summary":"FSA says Farm Operating Loans can finance livestock, seed, equipment, farm operating costs, and family living expenses while a farm gets started. The page states an amount up to $400,000 for eligible borrowers. Individual eligibility requirements are not normalized in this listing.","listing.applicant_types":["farmers","ranchers"],"listing.opportunity_url":"https://www.farmers.gov/loans","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed","criteria_program_ids":["usda-fsa-direct-farm-loans","usda-fsa-guaranteed-farm-loan"],"criteria_link_evidence":{"links":[{"program_id":"usda-fsa-direct-farm-loans","source_urls":["https://www.farmers.gov/loans","https://www.fsa.usda.gov/programs-and-services/farm-bill/farm-loans/farm-operating-loans-and-microloans"],"relationship":"FSA direct farm-operating loan listing"},{"program_id":"usda-fsa-guaranteed-farm-loan","source_urls":["https://www.farmers.gov/loans","https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans"],"relationship":"FSA guaranteed farm-operating loan listing"}],"status":"review_only","reviewed_date":"2026-10-29","policy_version":"fsa-loan-criteria-links-v1"}}'::jsonb, '{"source_id":"usda.farmers.gov","effective_at":null,"retrieved_at":"2026-10-27T02:48:30Z","source_version":"Farmers.gov Loans page SHA-256 9fa6f046735bf89b6998d9942779b16a7da28e29d387f2fda174c03f843f22c7","field_provenance":{"listing.title":{"so