INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('farmers-gov-farm-finance-listings', 'fsa-marketing-assistance-loans', 'federal-farm-finance-listing', '{"listing.title":"FSA Marketing Assistance Loans","listing.agency":"Farm Service Agency (FSA), USDA","listing.summary":"Farmers.gov says Marketing Assistance Loans provide producers interim financing at harvest so they may meet cash-flow needs without selling commodities when prices are typically low. Commodity and program rules are not normalized in this listing.","listing.applicant_types":["agricultural_producers"],"listing.opportunity_url":"https://www.farmers.gov/loans","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"usda.farmers.gov","effective_at":null,"retrieved_at":"2026-10-27T02:48:30Z","source_version":"Farmers.gov Loans page SHA-256 9fa6f046735bf89b6998d9942779b16a7da28e29d387f2fda174c03f843f22c7","field_provenance":{"listing.title":{"source_url":"https://www.farmers.gov/loans","observed_at":"2026-10-27T02:48:30Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.farmers.gov/loans","observed_at":"2026-10-27T02:48:30Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.farmers.gov/loans","observed_at":"2026-10-27T02:48:30Z","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://www.farmers.gov/loans","observed_at":"2026-10-27T02:48:30Z","extraction_method":"operator_review"},"listing.opportunity_url":{"source_url":"https://www.farmers.gov/loans","observed_at":"2026-10-27T02:48:30Z","extraction_method":"operator_review"},"core.geograph