INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('hud-hcv-income-screen', 'hud-housing-choice-voucher', 'eligibility_program', '{"core.geography.state_code":"MO","eligibility.program.title":"Housing Choice Voucher — St. Louis City FY2026 general VLI income screen","core.geography.county_name":"St. Louis City","core.geography.country_code":"US","eligibility.program.details":[{"kind":"application_step","text":"As of 2026-11-04, SLHA reported that the Housing Choice Voucher waiting list was closed and it was not accepting applications. Check SLHA for current status before applying. When the list opens, SLHA says applications are submitted online through RentCafe; applying is free.","source_id":"us.slha.housing-choice-voucher"},{"kind":"application_step","text":"For HCV application or waitlist questions, contact SLHA Section 8 at (314) 286-4303. SLHA also lists (314) 531-4770 for application-status questions and TDD (314) 286-4223 for accessibility.","source_id":"us.slha.housing-contact"},{"kind":"required_document","text":"HUD says documentation varies by PHA. Common items to prepare may include income paperwork such as pay stubs and bank information; public-assistance paperwork such as SSI or SNAP if applicable; and proof of citizenship plus Social Security cards. Confirm the actual checklist with SLHA; this is preparation guidance, not a verified SLHA mandatory-document list.","source_id":"us.hud.hcv-applicant-resources"}],"eligibility.program.criteria":[{"value":{"1":39750},"operator":"lte_by","attribute":"core.household.annual_income_usd","source_id":"us.hud.income-limits","criterion_id":"hcv-stlouis-one-person-vli-income-fy2026","context_attribute":"core.household.size"}],"eligibility.program.navigator":"low_income_assistance","eligibility.program.program_id":"hud-housing-choice-voucher","eligibility.program.data_origin":"public_source","eligibility.program.description":"Partial comparison of the published HUD very-low-income income limit for a one-person family in the St. Louis, MO-IL HMFA. An above-limit result means only that the synthetic income is above the general VLI screen; qualifying low-income families may still meet the published 80% AMI pathway. SLHA''s HCV page reported its waitlist closed on 2026-11-04. This is not an HCV eligibility decision.","core.geography.jurisdiction_level":"local","eligibility.program.catalog_version":"hud-hcv-stlouis-income-fy2026","eligibility.program.source_references":[{"url":"https://www.slha.org/find-a-home/housing-choice-voucher-program/","title":"Housing Choice Voucher Program","agency":"St. Louis Housing Authority","source_id":"us.slha.housing-choice-voucher","source_type":"public_source","jurisdiction":{"level":"local","state_code":"MO","county_name":"St. Louis City","country_code":"US"},"retrieved_at":"2026-11-04T21:17:53Z","effective_date":null,"approval_status":"approved","contract_version":"source-reference-v1","publisher_version":"SLHA HCV page reviewed 2026-11-04; waitlist reported closed"},{"url":"https://www.slha.org/contact-us/","title":"Contact Us","agency":"St. Louis Housing Authority","source_id":"us.slha.housing-contact","source_type":"public_source","jurisdiction":{"level":"local","state_code":"MO","county_name":"St. Louis City","country_code":"US"},"retrieved_at":"2026-11-06T19:13:44Z","effective_date":null,"approval_status":"approved","contract_version":"source-reference-v1","publisher_version":"SLHA contact page reviewed 2026-11-06"},{"url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","title":"Housing Choice Voucher Applicant and Tenant Resources","agency":"U.S. Department of Housing and Urban Development","source_id":"us.hud.hcv-applicant-resources","source_type":"public_source","jurisdiction":{"level":"federal","country_code":"US"},"retrieved_at":"2026-11-06T19:13:44Z","effective_date":null,"approval_status":"approved","contract_version":"source-reference-v1","publisher_version":"HUD HCV Applicant and Tenant Resources reviewed 2026-11-06"}]}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"local","state_code":"MO","region_code":"ST-LOUIS-CITY","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"reviewed_at":"2026-11-04T21:04:28Z","source_content_sha256":"9ab4e7368299aa61f63fb3cfe566d05f64224a40910c0ed77fd5f50ecb8da3a7","mapped_requirement_ids":["hcv-stlouis-one-person-vli-income-fy2026"],"unresolved_requirement_ids":["hcv-low-income-exceptions-above-vli","hcv-other-admission-requirements","slha-current-waitlist-and-application-availability"]}}'::jsonb, '{"publisher":"U.S. Department of Housing and Urban Development, Office of Policy Development and Research","source_id":"us.hud.income-limits","limitations":["The threshold table contains only household size 1 and applies only to the St. Louis, MO-IL HMFA; other sizes and areas remain unknown.","Above $39,750 is above the general very-low-income screen, not a complete HCV ineligibility result. SLHA describes low-income families up to 80% of area median income as an eligible income category; this record does not map that pathway.","The record is scoped to St. Louis City for UC-3-S2 and is not generalized to St. Louis County or other PHA jurisdictions.","SLHA''s HCV page reported on 2026-11-04 that its waitlist was closed and not accepting applications. This is time-sensitive application availability, not a criteria outcome; confirm directly with the PHA before action.","SLHA''s income-limits page shows $39,750 for one person but has no visible effective year and differs from HUD FY2026 by $50 for household sizes 7 and 8. Only the one-person threshold is used here; the HUD FY2026 PDF is the rule''s threshold source.","The Core source reader permits SLHA''s .org domain class for discovery but reports it as unverified. The operator-reviewed local application details are context and instructions, not executable eligibility rules.","Citizenship or eligible non-citizen status, household and admission conditions, local preferences, application windows, funding, and housing availability are not evaluated. Check the local PHA before action."],"source_type":"public_source","effective_at":"2026-05-01T00:00:00Z","retrieved_at":"2026-11-04T21:04:28Z","source_title":"FY2026 Section 8 Income Limits — St. Louis, MO-IL HMFA","effective_date":"2026-05-01","source_version":"FY2026 Section 8 Income Limits; released 2026-05-01; SHA-256 9ab4e7368299aa61f63fb3cfe566d05f64224a40910c0ed77fd5f50ecb8da3a7","approval_status":"approved","field_provenance":{"core.geography.state_code":{"source_url":"https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf","observed_at":"2026-11-04T21:04:28Z","extraction_method":"operator_review"},"eligibility.program.title":{"source_url":"https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf","observed_at":"2026-11-04T21:04:28Z","extraction_method":"operator_review"},"core.geography.county_name":{"source_url":"https://www.slha.org/find-a-home/housing-choice-voucher-program/","observed_at":"2026-11-04T21:00:53Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf","observed_at":"2026-11-04T21:04:28Z","extraction_method":"operator_review"},"eligibility.program.details":{"source_url":"https://www.slha.org/find-a-home/housing-choice-voucher-program/","observed_at":"2026-11-04T21:17:53Z","extraction_method":"operator_review"},"eligibility.program.criteria":{"source_url":"https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf","observed_at":"2026-11-04T21:04:28Z","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-11-04T21:00:52Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-11-04T21:00:52Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-11-04T21:00:52Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.slha.org/find-a-home/housing-choice-voucher-program/","observed_at":"2026-11-04T21:17:53Z","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://www.slha.org/find-a-home/housing-choice-voucher-program/","observed_at":"2026-11-04T21:00:53Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf","observed_at":"2026-11-04T21:04:28Z","extraction_method":"operator_review"},"eligibility.program.source_references":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-11-06T19:13:44Z","extraction_method":"operator_review"}},"criteria_coverage":"partial","transform_version":"hud-hcv-vli-income-screen-v1","raw_payload_stored":false,"source_content_sha256":"9ab4e7368299aa61f63fb3cfe566d05f64224a40910c0ed77fd5f50ecb8da3a7"}'::jsonb, 'https://www.huduser.gov/portal/datasets/il/il26/Section8-IncomeLimits-FY26.pdf', '1bb1fb3a5c61f3dc2796b2925a21d03fa6219afc7732f11c9b696b2f05f80ff2', 'eligibility-program-v4', '2026-11-04T21:04:28+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('hud-housing-assistance-referrals', 'hud-housing-choice-voucher', 'federal-benefit-program-listing', '{"listing.title":"Housing Choice Voucher (HCV) Program","listing.agency":"U.S. Department of Housing and Urban Development","listing.summary":"HUD''s Housing Choice Voucher program helps eligible households rent privately owned housing. HUD directs applicants to apply through local Public Housing Agencies (PHAs). Published HUD information identifies income, family size, citizenship or eligible non-citizen status, and other program conditions; income limits, waitlists, application availability, and local administration must be checked with the relevant PHA. This listing is discovery information only, not an eligibility result.","listing.applicant_types":["low-income households","families","older adults","people with disabilities"],"listing.opportunity_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"us.hud.housing-assistance","effective_at":null,"retrieved_at":"2026-10-30T01:21:12Z","source_version":"Official HUD Housing Choice Voucher, public housing, and PHA contact pages reviewed 2026-10-30; no publisher revision date recorded.","field_provenance":{"listing.title":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.hud.gov/topics/housing_choice_voucher_program_section_8","observed_at":"2026-10-30T01:21:12Z","extraction_