INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('hud-housing-assistance-referrals', 'hud-pha-contact-directory', 'federal-program-referral', '{"listing.title":"HUD Public Housing Agency (PHA) Contact Directory","listing.agency":"U.S. Department of Housing and Urban Development","listing.summary":"HUD''s PHA directory provides contact information by state for finding a local agency to ask about public housing and Housing Choice Voucher assistance. HUD states the contact information is updated weekly and PHAs maintain their own records. Use the selected PHA to verify local program availability, current application windows, and requirements.","listing.applicant_types":["people seeking public housing or rental assistance"],"listing.opportunity_url":"https://www.hud.gov/program_offices/public_indian_housing/pha/contacts","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"referral","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"us.hud.housing-assistance","effective_at":null,"retrieved_at":"2026-10-30T01:21:12Z","source_version":"Official HUD Housing Choice Voucher, public housing, and PHA contact pages reviewed 2026-10-30; no publisher revision date recorded.","field_provenance":{"listing.title":{"source_url":"https://www.hud.gov/program_offices/public_indian_housing/pha/contacts","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.hud.gov/program_offices/public_indian_housing/pha/contacts","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.hud.gov/program_offices/public_indian_housing/pha/contacts","observed_at":"2026-10-30T0