INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('hud-housing-assistance-referrals', 'hud-public-housing', 'federal-benefit-program-listing', '{"listing.title":"Public Housing","listing.agency":"U.S. Department of Housing and Urban Development","listing.summary":"HUD funds local Public Housing Agencies to provide and manage public housing. HUD describes public housing as serving low-income individuals and families, including older adults and people with disabilities. A local PHA determines eligibility and administers applications; local availability and waiting lists must be checked with that agency. This listing is discovery information only, not an eligibility result.","listing.applicant_types":["low-income households","families","older adults","people with disabilities"],"listing.opportunity_url":"https://www.hud.gov/topics","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"us.hud.housing-assistance","effective_at":null,"retrieved_at":"2026-10-30T01:21:12Z","source_version":"Official HUD Housing Choice Voucher, public housing, and PHA contact pages reviewed 2026-10-30; no publisher revision date recorded.","field_provenance":{"listing.title":{"source_url":"https://www.hud.gov/topics","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.hud.gov/topics","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.hud.gov/topics","observed_at":"2026-10-30T01:21:12Z","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://www.hud.gov/topi