INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('kansas-dcf-snap-residency-guidance', 'kansas-snap-residency', 'eligibility_program', '{"core.geography.state_code":"KS","eligibility.program.title":"Kansas Food Assistance residency guidance (partial criteria)","core.geography.country_code":"US","eligibility.program.criteria":[{"value":"KS","operator":"eq","attribute":"core.geography.state_code","source_id":"kansas.dcf.food-assistance-residency","criterion_id":"kansas-snap-residency"}],"eligibility.program.navigator":"low_income_assistance","eligibility.program.program_id":"kansas-snap-residency","eligibility.program.data_origin":"public_source","eligibility.program.description":"The checked-in V1 source mapping and current Kansas DCF KEESM 2150 source support only the Kansas residence criterion. A matching state_code is not a full SNAP eligibility determination; income, resources, household composition, and other program rules are outside this record.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"KEESM-2150-current-2026-11-11"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"KS","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"citations":[{"excerpt":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","source_id":"kansas.dcf.food-assistance-residency","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","requirement_id":"kansas-snap-residency"}],"reviewed_at":"2026-11-11T00:07:52.002328+00:00","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e