INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('maryland-ohep-published-criteria', 'md-ohep-ara-published-criteria', 'maryland-ohep-published-criteria-reference', '{"core.geography.state_code":"MD","eligibility.program.title":"Maryland Arrearage Retirement Assistance published requirements","core.geography.country_code":"US","eligibility.program.program_id":"md-ohep-ara","eligibility.program.data_origin":"Maryland DHS OHEP official program pages reviewed 2026-10-31: https://dhs.maryland.gov/office-of-home-energy-programs/about-energy-assistance/ and https://dhs.maryland.gov/office-of-home-energy-programs/how-are-grants-determined/. Published statements are partial and not executable.","eligibility.program.description":"OHEP describes a minimum past-due balance and recurrence limits; the grant amount and EUSP prerequisite are published separately. The record is review-only and does not evaluate a household.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"md-ohep-ara-reviewed-2026-10-31","eligibility.program.published_requirements":[{"source_id":"maryland.ohep","statement":"The applicant must have a past-due bill of at least $300 to be considered. The page lists up to $2,000 for electric arrears and up to $1,000 for gas arrears, generally once every five years with stated exceptions. OHEP''s grant-determination page says an ARA applicant must be eligible for EUSP. These are published facts; no executable rule or full criteria mapping is supplied.","mapping_status":"not_mapped","requirement_id":"ohep-ara-arrearage-and-frequency"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"state","state_code":"MD","country_code":"US"},"effective_period":"Current OHEP page; exact inclusive date range not asserted","catalog_namespace":"programs","criteria_coverage":"partial",