":"https://dhs.maryland.gov/office-of-home-energy-programs/how-are-grants-determined/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/how-are-grants-determined/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"}},"transform_version":"md-ohep-source-review-v1","raw_payload_stored":false}'::jsonb, 'https://dhs.maryland.gov/office-of-home-energy-programs/how-are-grants-determined/', 'ab796c3e30ca533ec2f91969229073d38b1fda71b3df404cba9ed35260722d24', 'eligibility-program-v2', '2026-10-31T22:47:17+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('maryland-ohep-published-criteria', 'md-ohep-meap-eusp-fy27-published-criteria', 'maryland-ohep-published-criteria-reference', '{"core.geography.state_code":"MD","eligibility.program.title":"Maryland OHEP MEAP and EUSP published requirements","core.geography.country_code":"US","eligibility.program.program_id":"md-ohep-meap-eusp","eligibility.program.data_origin":"Maryland DHS OHEP official pages reviewed 2026-10-31: https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/ and https://dhs.maryland.gov/office-of-home-energy-programs/how-are-grants-determined/. Published statements are review-only and not executable.","eligibility.program.description":"Current OHEP pages label the displayed monthly household income limits FY27. The pages describe household-size income limits and program-specific grant factors. This record preserves those published facts for later criteria mapping; it does not calculate eligibility or a grant amount.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"md-ohep-fy27-reviewed-2026-10-31","eligibility.program.published_requirements":[{"source_id":"maryland.ohep","statement":"Maryland OHEP''s current application page labels the following monthly household income limits FY27. Household size 1-10: $2,660; $3,607; $4,553; $5,500; $6,447; $7,393; $8,340; $9,287; $10,233; and $11,180. For household size 11 or more, contact the local OHEP office. The FAQ describes the factor as income earned in the last 30 days; no income-exclusion or categorical-rule detail is mapped here.","mapping_status":"not_mapped","requirement_id":"ohep-fy27-monthly-income-limits-meap-eusp"},{"source_id":"maryland.ohep","statement":"The application page lists applicant photo ID, proof of residency, Social Security cards for household members, gross income for the last 30 days, and a utility/heating bill among information needed. OHEP offers online, mail, telephone, drop-box, and in-person application paths. These are documentation/application steps, not profile eligibility rules.","mapping_status":"context_only","requirement_id":"ohep-application-and-proof-context"},{"source_id":"maryland.ohep","statement":"MEAP grant amounts depend on fuel type, household income, and area within Maryland. EUSP grant amounts depend on household income and electric use over the prior 12 months. These factors do not specify a complete benefit calculation in this catalog record.","mapping_status":"not_mapped","requirement_id":"ohep-grant-calculation-factors"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"state","state_code":"MD","country_code":"US"},"effective_period":"FY27 as labeled by current OHEP page; exact inclusive date range not asserted","catalog_namespace":"programs","criteria_coverage":"partial","criteria_program_ids":["md-ohep-meap","md-ohep-eusp"],"criteria_mapping_status":"not_mapped"}'::jsonb, '{"publisher":"Maryland Department of Human Services","source_id":"maryland.ohep","source_type":"public_source","effective_at":null,"retrieved_at":"2026-10-31T22:47:17Z","source_title":"Maryland Office of Home Energy Programs","source_version":"Maryland DHS OHEP public pages reviewed 2026-10-31; FY27 guidance where labeled","approval_status":"approved","criteria_status":"partial_not_mapped","field_provenance":{"core.geography.state_code":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.title":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/","observed_at":"2026-10-31T22:47:17Z","extraction_method":"operator_review"}},"transform_version":"md-ohep-source-review-v1","raw_payload_stored":false}'::jsonb, 'https://dhs.maryland.gov/office-of-home-energy-programs/apply-energy-assistance/', 'f9263ee721c2af5881dd1b53022f469f8533ae21139618ed188632db79609e70', 'eligibility-program-v2', '2026-10-31T22:47:17+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-dese-child-care-subsidy-listings', 'missouri-child-care-subsidy', 'public_listing', '{"listing.title":"Missouri Child Care Subsidy","listing.agency":"Missouri Department of Elementary and Secondary Education","listing.summary":"Missouri DESE child care subsidy helps eligible families pay for care to support early learning. The official page describes qualifying activities, child age and exception conditions, and an income limit; this listing does not assess eligibility.","listing.program_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","listing.record_kind":"assistance_program","listing.applicant_types":["parent","guardian","family with children"],"listing.assistance_type":"child care subsidy for working, job-seeking, training, or student families","core.geography.state_code":"MO","core.geography.country_code":"US","listing.applicant_description":"Missouri families seeking child care assistance for work, job search, job training, or school; consult the official source for current program details.","listing.beneficiary_description":"Missouri families seeking child care assistance to support access to early learning.","core.geography.jurisdiction_level":"state"}'::jsonb, '{"need_topics":["child_care_assistance","work_support","job_training","education"],"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"listing_kind":"assistance_program","catalog_namespace":"programs","criteria_coverage":"not_assessed","beneficiary_classes":["Missouri families with children"],"criteria_program_ids":["missouri-child-care-subsidy"],"criteria_link_evidence":{"links":[{"program_id":"missouri-child-care-subsidy","source_urls":["https://dese.mo.gov/childhood/child-care-subsidy/families"],"relationship":"Misso