INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-dese-child-care-subsidy-mapped-criteria', 'missouri-child-care-subsidy', 'eligibility_program', '{"core.geography.state_code":"MO","eligibility.program.title":"Missouri Child Care Subsidy partial child qualification and qualifying-need screen","core.geography.country_code":"US","eligibility.program.criteria":[{"value":13,"operator":"lte","attribute":"mo.dese.childcare.child_age_years","source_id":"missouri.dese.child-care-subsidy","criterion_id":"mo-childcare-child-age-at-most-13"},{"value":["work","job_search","job_training","school"],"operator":"one_of","attribute":"mo.dese.childcare.qualifying_activity","source_id":"missouri.dese.child-care-subsidy","criterion_id":"mo-childcare-qualifying-activity"},{"value":true,"operator":"eq","attribute":"mo.dese.childcare.care_needed_for_qualifying_activity","source_id":"missouri.dese.child-care-subsidy","criterion_id":"mo-childcare-care-needed-for-qualifying-activity"}],"eligibility.program.navigator":"low_income_assistance","eligibility.program.program_id":"missouri-child-care-subsidy","eligibility.program.data_origin":"public_source","eligibility.program.description":"Compares only the page-supported child age-through-13 clause, a listed qualifying activity, and whether child care is needed for that activity. Special-needs and protective-services exceptions, income, local availability, and other case-specific conditions remain unresolved.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"dese-childcare-mapped-criteria-2026-11-09"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"citations":[{"excerpt":"Have a child birth to age 13","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","requirement_id":"mo-childcare-child-age-at-most-13"},{"excerpt":"work, search for work, participate in job training, or attend school","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","requirement_id":"mo-childcare-qualifying-activity"},{"excerpt":"Need child care to","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","requirement_id":"mo-childcare-care-needed-for-qualifying-activity"}],"reviewed_at":"2026-11-10T02:34:59.916718+00:00","source_record_id":"source-page-37a0c7616c5aaddbbe10","source_content_sha256":"25fc58e541edae1df604c65f4972385b6774d8356b80debe824928c620c49fbc","mapped_requirement_ids":["mo-childcare-child-age-at-most-13","mo-childcare-qualifying-activity","mo-childcare-care-needed-for-qualifying-activity"],"source_policy_reference":{"policy_id":"eligibility-public-search-domains","content_sha256":"a78aff8eff8fd47d04481602684cdcdc6e55bd80e16458e32c270adbb6e22e24","policy_version":"1.2.4"},"source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6","unresolved_requirement_ids":["mo-childcare-special-needs-exception","mo-childcare-protective-services-exception","mo-childcare-income-at-or-below-150-percent-fpl","local-enrollment-and-availability","additional-application-and-case-specific-conditions"]}}'::jsonb, '{"publisher":"Missouri Department of Elementary and Secondary Education","source_id":"missouri.dese.child-care-subsidy","limitations":["Only the family page''s child birth-to-age-13 clause is mapped; special-needs and protective-services exception pathways remain unmapped pending a controlling policy crosswalk.","Listed activities are work, job search, job training, and school; the profile must also state that child care is needed for the activity.","The 150% FPL income condition is not evaluated because its controlling policy version, income basis, and household-size thresholds are unresolved.","Local service availability and additional case-specific conditions remain unresolved.","A mapped outcome is a partial screening comparison, not a Missouri DESE eligibility decision or application result."],"source_type":"public_source","effective_at":null,"retrieved_at":"2026-11-10T02:34:59.916718+00:00","source_title":"Child Care Subsidy Information for Families","source_version":"sha256:25fc58e541edae1df604c65f4972385b6774d8356b80debe824928c620c49fbc","approval_status":"approved","field_provenance":{"core.geography.state_code":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.title":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.criteria":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","observed_at":"2026-11-10T02:34:59.916718+00:00","extraction_method":"operator_review"}},"source_record_id":"source-page-37a0c7616c5aaddbbe10","criteria_coverage":"partial","transform_version":"missouri-child-care-typed-criteria-map-v2","raw_payload_stored":false,"source_content_sha256":"25fc58e541edae1df604c65f4972385b6774d8356b80debe824928c620c49fbc","source_policy_reference":{"policy_id":"eligibility-public-search-domains","content_sha256":"a78aff8eff8fd47d04481602684cdcdc6e55bd80e16458e32c270adbb6e22e24","policy_version":"1.2.4"},"source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6"}'::jsonb, 'https://dese.mo.gov/childhood/child-care-subsidy/families', '8a32aceb584b273620349f71c1452e175dfda05d8859cdffafca7764cc5ea5d1', 'eligibility-program-v2', '2026-11-10T02:34:59.916718+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-dss-snap-guidance', 'missouri-snap-current-20261108', 'public_listing', '{"listing.title":"Missouri SNAP application guidance","listing.agency":"Missouri Department of Social Services","listing.status":"unknown","listing.summary":"Missouri SNAP provides monthly food benefits. The official page lists Missouri residency, household Social Security numbers, current income and resource limits, and case-specific exclusions, plus steps to apply, submit an application, and complete an interview if required. Only Missouri residency is currently executable; remaining criteria are unresolved.","listing.program_url":"https://dss.mo.gov/food-assistance/apply-for-snap","listing.record_kind":"assistance_program","listing.applicant_types":["Missouri households seeking food assistance"],"core.geography.state_code":"MO","core.geography.country_code":"US","core.geography.jurisdiction_level":"state"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"listing_kind":"assistance_program","catalog_namespace":"programs","criteria_coverage":"partial","criteria_program_ids":["missouri-snap"]}'::jsonb, '{"publisher":"Missouri Department of Social Services","source_id":"missouri.dss.snap","source_type":"public_source","effective_at":null,"retrieved_at":"2026-11-08T23:22:34.399696Z","source_title":"Apply for SNAP | Missouri Department of Social Services","source_version":"sha256:9465d73be1c496d78d4c49497b0388c3a2c24a03d8bbf0af10d9ed4e7ad66c5b","approval_status":"approved","criteria_status":"not_assessed","field_provenance":{"listing.title":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-08T23:22:34.399696Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"h