INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-dss-temporary-assistance-listings', 'missouri-temporary-assistance', 'public_listing', '{"listing.title":"Missouri Temporary Assistance","listing.agency":"Missouri Department of Social Services, Family Support Division","listing.summary":"Missouri Temporary Assistance is a cash benefit for low-income families to help cover costs for children. Approved participants must take part in Missouri Work Assistance employment and training services. This listing does not map or evaluate the program’s eligibility conditions.","listing.program_url":"https://dss.mo.gov/temporary-assistance/apply","listing.record_kind":"assistance_program","listing.applicant_types":["parent","guardian","family with children"],"listing.assistance_type":"temporary cash assistance for families","core.geography.state_code":"MO","core.geography.country_code":"US","listing.applicant_description":"Missouri parents or guardians seeking cash assistance for a household with children; consult the state page for current application details.","listing.beneficiary_description":"Low-income families with children in Missouri","core.geography.jurisdiction_level":"state"}'::jsonb, '{"need_topics":["temporary_cash_assistance","family_stability"],"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"listing_kind":"assistance_program","catalog_namespace":"programs","criteria_coverage":"not_assessed","beneficiary_classes":["Missouri families with children"]}'::jsonb, '{"publisher":"Missouri Department of Social Services","source_id":"missouri.dss.temporary-assistance","source_type":"public_source","effective_at":null,"retrieved_at":"2026-11-09T17:45:09.542026+00:00","source_title":"Apply for Temporary Assistance","source_notice":"Published program statements are review evidence only. This listing is not a complete screening rule or an official eligibility decision.","source_version":"sha256:a291c07178c367d0378f2decefbcb590ba609dcb50f09612a3aa20d6c8696ccf","approval_status":"approved","criteria_status":"not_assessed","field_provenance":{"listing.title":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.program_url":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.record_kind":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.assistance_type":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"core.geography.state_code":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.applicant_description":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"listing.beneficiary_description":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://dss.mo.gov/temporary-assistance/apply","observed_at":"2026-11-09T17:45:09.542026+00:00","extraction_method":"operator_review"}},"transform_version":"missouri-ta-source-refresh-review-v1","raw_payload_stored":false}'::jsonb, 'https://dss.mo.gov/temporary-assistance/apply', 'a291c07178c367d0378f2decefbcb590ba609dcb50f09612a3aa20d6c8696ccf', 'public-listing-v3', '2026-11-09T17:45:09.542026+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-snap-application-details', 'missouri-snap', 'eligibility_program', '{"core.geography.state_code":"MO","eligibility.program.title":"Missouri SNAP application and processing guidance","core.geography.country_code":"US","eligibility.program.details":[{"kind":"application_step","text":"Apply online, print and complete a paper application, or request that a printed application be mailed to you. The page links an English and Spanish application and says Adobe Reader is required for the download.","source_id":"missouri.dss.snap"},{"kind":"application_step","text":"Submit completed application forms online at mydssupload.mo.gov, by mail to Family Support Division, P.O. Box 2700, Jefferson City, MO 65102, or by fax at 573-526-9400.","source_id":"missouri.dss.snap"},{"kind":"application_step","text":"If an interview is required, FSD will call after receiving the application. If you miss the call, visit a local resource center or call 855-823-4908 to complete the interview.","source_id":"missouri.dss.snap"},{"kind":"deadline","text":"Missouri DSS says applicants typically learn whether they are approved within 30 days. FSD says processing an application and supporting documentation can take up to 10 days after receipt; this is a stated processing estimate, not an applicant submission deadline.","source_id":"missouri.dss.snap"},{"kind":"deadline","text":"In some emergency cases, SNAP benefits may be available in seven days or less. The page says to complete Section 2 of the SNAP application or tell FSD at submission if the emergency questions apply; this does not guarantee expedited benefits.","source_id":"missouri.dss.snap"}],"eligibility.program.criteria":[{"value":"MO","operator":"eq","attribute":"core.geography.state_code","source_id":"missouri.dss.snap","criterion_id":"residency-missouri"},{"value":true,"operator":"eq","attribute":"snap.all_members_have_or_applying_ssn","source_id":"missouri.dss.snap","criterion_id":"all-members-have-or-applying-ssn"}],"eligibility.program.navigator":"low_income_assistance","eligibility.program.program_id":"missouri-snap","eligibility.program.data_origin":"public_source","eligibility.program.description":"Source-backed application and submission instructions, interview contingency, and processing timelines for the existing Missouri SNAP listing. Missouri residency and the household SSN condition are mapped; income, resources, and member-specific conviction or fugitive restrictions remain unresolved.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"missouri-snap-application-details-2026-11-10"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial"}'::jsonb, '{"publisher":"Missouri Department of Social Services","source_id":"missouri.dss.snap","limitations":["This is a supporting program-details record for the existing Missouri SNAP listing; it does not add a second public listing.","Missouri residency and the household SSN condition are mapped. Current income limits, resources, and member-specific conviction or fugitive restrictions remain unresolved.","The source links to Verification Documents but does not enumerate a required-document checklist; no required documents are asserted.","The 10-day statement describes FSD processing time, not a deadline for the applicant. Typical and emergency processing times are not guarantees."],"source_type":"public_source","effective_at":null,"retrieved_at":"2026-11-10T09:03:13.064667+00:00","source_title":"Apply for SNAP | Missouri Department of Social Services","source_version":"sha256:0ce7923a474bed7e4e3dc7f9f0557375b47049c6ec8667515a9c56ffb74d47d6","approval_status":"approved","field_provenance":{"core.geography.state_code":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.title":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.details":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.criteria":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","observed_at":"2026-11-10T09:03:13.064667+00:00","extraction_method":"operator_review"}},"criteria_coverage":"partial","transform_version":"missouri-snap-application-details-v1","raw_payload_stored":false}'::jsonb, 'https://dss.mo.gov/food-assistance/apply-for-snap', 'e421b028313bd2e0867d21fac6199710df5e1e1f7792e3865f2fb78a003369be', 'eligibility-program-v4', '2026-11-10T09:03:13.064667+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('missouri-ta-residency-mapped-criteria', 'missouri-temporary-assistance', 'eligibility_program', '{"core.geography.state_code":"MO","eligibility.program.title":"Missouri Temporary Assistance (partial screening criteria)","core.geography.country_code":"US","eligibility.program.criteria":[{"value":"MO","operator":"eq","attribute":"core.geography.state_code","source_id":"missouri.dss.temporary-assistance","criterion_id":"missouri-ta-residency"}],"eligibility.program.navigator":"low_income_assistance","eligibility.program.program_id":"missouri-temporary-assistance","eligibility.program.data_origin":"public_source","eligibility.program.description":"Partial screening of the published Missouri residence criterion only. Child age and parent/guardian relationship, current resource and income limits, household Social Security Number conditions, drug-test requirement and case-specific exclusions, post-approval employment and training obligations, and full state adjudication are not evaluated.","core.geography.jurisdiction_level":"state","eligibility.program.catalog_version":"missouri-ta-reviewed-2026-11-03"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"state","state_code":"MO","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"citations":[{"excerpt":"Live in Missouri","source_id":"missouri.dss.temporary-assistance","source_url":"https://dss.mo.gov/temporary-assistance/apply","requirement_id":"missouri-ta-residency"}],"reviewed_at":"2026-11-10T02:44:37.912753+00:00","source_record_id":"source-page-63ef48e56e04eb5ad105","source_content_sha256":"ecdb8e54999c99f4dd79e7e46cfdc33f0e480a408cbd36f27115aee6f25e4af8","mapped_requirement_ids":["missouri-ta-residency"],"source_visible_text_sha256":"6985