INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('nrcs-eqip-mapped-criteria', 'usda-nrcs-eqip', 'eligibility_program', '{"eligibility.program.title":"Environmental Quality Incentives Program (EQIP) partial land-control screen","core.geography.country_code":"US","eligibility.program.criteria":[{"value":true,"operator":"eq","attribute":"nrcs.eqip.fsa_records_confirm_eligible_land_control","source_id":"usda.nrcs.eqip","criterion_id":"eqip-fsa-records-eligible-land-control"}],"eligibility.program.navigator":"farmer_producer","eligibility.program.program_id":"usda-nrcs-eqip","eligibility.program.data_origin":"public_source","eligibility.program.description":"Compares only whether FSA farm records indicate the applicant controls or owns eligible land. Eligible applicant and land categories, AGI/payment limitations, conservation compliance, plan requirements, state ranking, and additional restrictions remain unresolved.","core.geography.jurisdiction_level":"federal","eligibility.program.catalog_version":"eqip-land-control-2026-11-05"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"reviewed_at":"2026-11-05T12:38:21.056195Z","source_content_sha256":"248551366cb90d86dd5b327c6eb02192a83ebd20e2449f7290d6658bd2064286","mapped_requirement_ids":["eqip-fsa-records-eligible-land-control"],"unresolved_requirement_ids":["eligible-applicant-category","eligible-land-category","agi-and-payment-limitations","highly-erodible-land-and-wetland-compliance","eqip-plan-of-operations","state-ranking-and-funding-priority","additional-local-restrictions"]}}'::jsonb, '{"publisher":"Natural Resources Conservation Service, U.S. Department of Agriculture","source_id":"usda.nrcs.eqip","limitations":["Only the published FSA farm-record condition for ownership or control of eligible land is compared.","The generic farmer profile does not establish the FSA record; collect the namespaced synthetic boolean explicitly.","A met result is not an EQIP eligibility or funding decision.","Other applicant, land, AGI, conservation-compliance, plan, ranking, and local conditions remain unresolved."],"source_type":"public_source","effective_at":null,"retrieved_at":"2026-11-05T12:38:21.056195Z","source_title":"Apply for Environmental Quality Incentives Program (EQIP)","source_version":"sha256:248551366cb90d86dd5b327c6eb02192a83ebd20e2449f7290d6658bd2064286","approval_status":"approved","field_provenance":{"eligibility.program.title":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-05T12:38:21.056195Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-05T12:38:21.056195Z","extraction_method":"operator_review"},"eligibility.program.criteria":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-05T12:38:21.056195Z","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-05T12:38:21.056195Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-05T12:38:21.056195Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://