INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('nrcs-eqip-program-listings', 'nrcs-eqip-application-guidance', 'federal-program-application-referral', '{"listing.title":"EQIP application, eligibility, and state ranking guidance","listing.agency":"Natural Resources Conservation Service (NRCS), USDA","listing.summary":"NRCS accepts EQIP financial-assistance applications throughout the year, but states set ranking and funding deadlines. Applicants are directed to a local NRCS office; the published application page lists eligible applicant and land categories, FSA farm-record requirements, and other requirements. Funding applications are ranked; this referral does not evaluate eligibility or likelihood of selection.","listing.applicant_types":["agricultural_producers","nonindustrial_private_forestland_owners","indian_tribes","agricultural_or_forestry_operation_interested_parties","water_management_entities"],"listing.opportunity_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"referral","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial"}'::jsonb, '{"source_id":"usda.nrcs.eqip","effective_at":null,"retrieved_at":"2026-11-03T23:53:26Z","source_version":"Official USDA NRCS EQIP program and application pages reviewed 2026-10-27; no publisher revision or effective date identified; listing summary reviewed 2026-11-03","field_provenance":{"listing.title":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.opportunity_url":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"}},"transform_version":"nrcs-eqip-official-page-review-2","raw_payload_stored":false}'::jsonb, 'https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality', '8fe8c77414579f515d75371084d705f05ed72ad7e0e3ada53144da8f968a9b46', 'public-listing-v1', '2026-10-27T02:56:30+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('nrcs-eqip-program-listings', 'nrcs-eqip-program', 'federal-conservation-program-listing', '{"listing.title":"Environmental Quality Incentives Program (EQIP)","listing.agency":"Natural Resources Conservation Service (NRCS), USDA","listing.summary":"USDA NRCS describes EQIP as voluntary technical and financial conservation assistance for agricultural producers and forest landowners on working lands. The New Mexico NRCS page lists irrigation-system improvements and water conservation among EQIP practices and resource concerns; practices, ranking, and funding vary by location and period. This listing does not determine eligibility or funding.","listing.applicant_types":["agricultural_producers","farmers","ranchers","forest_landowners"],"listing.opportunity_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_program_ids":["usda-nrcs-eqip"],"criteria_link_evidence":{"links":[{"program_id":"usda-nrcs-eqip","source_urls":["https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality"],"relationship":"Federal EQIP program identity is linked to its separately stored NRCS criteria reference and partial mapped-rule record.","criteria_record_id":"nrcs-eqip-published-criteria"}],"reviewed_at":"2026-11-05T12:42:00Z","policy_version":"scenario-mapped-criteria-links-v1"}}'::jsonb, '{"source_id":"usda.nrcs.eqip","effective_at":null,"retrieved_at":"2026-11-03T23:53:26Z","source_version":"Official USDA NRCS EQIP program and application pages reviewed 2026-10-27; no publisher revision or effective date identified; listing summary reviewed 2026-11-03","field_provenance":{"listing.title":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/new-mexico/environmental-quality","observed_at":"2026-11-03T23:30:53Z","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"listing.opportunity_url":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program","observed_at":"2026-10-27T02:56:30Z","extraction_method":"operator_review"}},"transform_version":"nrcs-eqip-official-page-review-2","raw_payload_stored":false}'::jsonb, 'https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program', '0ad3038dd3e8ee22a1e399154ce55c40492fa6417ab133bb38f856b2458c6c9a', 'public-listing-v1', '2026-11-03T23:30:53+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('nrcs-eqip-published-criteria', 'nrcs-eqip-published-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"Environmental Quality Incentives Program (EQIP) published eligibility reference","eligibility.program.details":[{"kind":"application_step","text":"Contact your local NRCS office to discuss whether EQIP fits your resource concern. If you proceed, a local NRCS conservationist will guide you through applying.","source_id":"usda.nrcs.eqip"},{"kind":"deadline","text":"Applications are accepted throughout the year. Each state sets specific deadlines for ranking and funding opportunities; confirm the applicable dates with NRCS.","source_id":"usda.nrcs.eqip"},{"kind":"application_step","text":"Establish or update Farm Service Agency records for both the applicant and the land. The records must indicate land control or ownership, adjusted-gross-income and payment-limit compliance, and highly-erodible-land and wetland-conservation compliance.","source_id":"usda.nrcs.eqip"},{"kind":"application_step","text":"After approval, participants work with an NRCS conservation planner to develop an EQIP plan of operations addressing at least one natural-resource concern.","source_id":"usda.nrcs.eqip"},{"kind":"form","text":"The NRCS page links to eForms to search for and complete the EQIP application form. Confirm the current form and instructions there.","source_id":"usda.nrcs.eqip"}],"eligibility.program.navigator":"farm_business_conservation","eligibility.program.program_id":"usda-nrcs-eqip","eligibility.program.data_origin":"USDA NRCS EQIP application guidance","eligibility.program.description":"Partial structured reference to requirements published on NRCS EQIP application guidance. Items are transcribed as source statements and remain unmapped to profile attributes or executable evaluation logic. The page warns that additional requirements may apply.","eligibility.program.catalog_version":"retrieved-2026-10-27","eligibility.program.published_requirements":[{"attribute":"nrcs.eqip.fsa_records_confirm_eligible_land_control","source_id":"usda.nrcs.eqip","statement":"Farm records must indicate that the applicant controls or owns eligible land.","concept_id":"eqip-fsa-records-eligible-land-control","mapping_status":"partial","requirement_id":"eqip-fsa-records-eligible-land-control","requirement_type":"eligibility"},{"source_id":"usda.nrcs.eqip","statement":"Eligible applicants include agricultural producers, owners of non-industrial private forestland, Indian Tribes, persons with an interest in agricultural or forestry operations, and water management entities.","mapping_status":"not_mapped","requirement_id":"eligible-applicant-category","requirement_type":"applicant_condition"},{"source_id":"usda.nrcs.eqip","statement":"Eligible land includes cropland and hayland, rangeland, pastureland, non-industrial private forestland, other farm or ranch lands, and environmentally sensitive areas.","mapping_status":"not_mapped","requirement_id":"eligible-land-category","requirement_type":"eligibility"},{"source_id":"usda.nrcs.eqip","statement":"Farm records must indicate that the applicant meets adjusted gross income and payment limitation provisions.","mapping_status":"not_mapped","requirement_id":"agi-and-payment-limitations","requirement_type":"eligibility"},{"source_id":"usda.nrcs.eqip","statement":"Farm records must indicate compliance with highly erodible land and wetland conservation requirements.","mapping_status":"not_mapped","requirement_id":"highly-erodible-land-and-wetland-compliance","requirement_type":"eligibility"},{"source_id":"usda.nrcs.eqip","statement":"Approved participants, with NRCS conservation planners, must develop an EQIP plan of operations addressing at least one natural resource concern.","mapping_status":"not_mapped","requirement_id":"eqip-plan-of-operations","requirement_type":"program_condition"},{"source_id":"usda.nrcs.eqip","statement":"Applications are ranked; state-specific cutoff dates and resource priorities affect consideration for funding, which is separate from eligibility.","mapping_status":"not_mapped","requirement_id":"state-ranking-and-funding-priority","requirement_type":"context"},{"source_id":"usda.nrcs.eqip","statement":"Additional restrictions and program requirements may apply; applicants should contact the local NRCS office for situation-specific information.","mapping_status":"not_mapped","requirement_id":"additional-local-restrictions","requirement_type":"context"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial"}'::jsonb, '{"source_id":"usda.nrcs.eqip","effective_at":null,"retrieved_at":"2026-11-09T21:48:19.380618Z","source_version":"sha256:231ada3d027aa98e5703f2710ffd9480f66abd11fc6cc8137aa00bb83e2cbfcc","field_provenance":{"eligibility.program.title":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.details":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","observed_at":"2026-11-09T21:48:19.380618Z","extraction_method":"operator_review"}},"transform_version":"nrcs-eqip-official-page-review-3","raw_payload_stored":false,"source_content_sha256":"231ada3d027aa98e5703f2710ffd9480f66abd11fc6cc8137aa00bb83e2cbfcc","source_visible_text_sha256":"e0405c6bb30e19eaa6aa4f2f9107b3a190423ce8ed57eea588b8cafc31e8a83d"}'::jsonb, 'https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality', '5d00f10adb19e14fcd94b850b2cd54f52667d11d796729a239303effb2cdce1f', 'eligibility-program-v4', '2026-11-09T21:48:19.380618+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usagov-benefit-discovery', 'usagov-benefit-finder', 'federal-program-referral', '{"listing.title":"USAGov benefit finder","listing.agency":"U.S. General Services Administration (USAGov)","listing.summary":"USAGov lets people select benefit categories—including children and families, disability, disaster, education, food, health, housing and utilities, jobs, military and veterans, retirement and seniors, and welfare/cash assistance—to find benefit information and application guidance. This is a discovery tool, not a program eligibility result.","listing.applicant_types":["individuals","families"],"listing.opportunity_url":"https://www.usa.gov/benefit-finder","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"referral","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"not_assessed"}'::jsonb, '{"source_id":"usagov.benefits","effective_at":null,"retrieved_at":"2026-10-28T19:42:37Z","source_version":"Official USA.gov pages reviewed 2026-10-28; visible page revision dates retained where available.","field_provenance":{"listing.title":{"source_url":"https://www.usa.gov/benefit-finder","observed_at":"2026-10-28T19:42:37Z","extraction_method":"operator_review"},"listing.agency":{"source_url":"https://www.usa.gov/benefit-finder","observed_at":"2026-10-28T19:42:37Z","extraction_method":"operator_review"},"listing.summary":{"source_url":"https://www.usa.gov/benefit-finder","observed_at":"2026-10-28T19:42:37Z","extraction_method":"operator_review"},"listing.applicant_types":{"source_url":"https://www.usa.gov/benefit-finder","observed_at":"2026-10-28T19:42:37Z","extraction_method":"operator_review"},"listing.opportunity_url":{"source_url":"https://www.usa.gov/ben