INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usagov-benefit-discovery', 'usagov-csfp-listing', 'federal-program-referral', '{"listing.title":"Commodity Supplemental Food Program (CSFP)","listing.agency":"U.S. General Services Administration (USAGov)","listing.summary":"USAGov identifies CSFP as a USDA program providing a monthly package of healthy food through local agencies; delivery may be available in some states. State participation and local administration vary.","listing.applicant_types":["older adults","low-income households"],"listing.opportunity_url":"https://www.usa.gov/senior-food-programs","core.geography.country_code":"US","core.geography.jurisdiction_level":"federal"}'::jsonb, '{"record_role":"referral","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_program_ids":["usda-csfp"],"criteria_link_evidence":{"links":[{"program_id":"usda-csfp","source_urls":["https://www.usa.gov/senior-food-programs","https://www.fns.usda.gov/csfp/factsheet"],"relationship":"USAGov names the Commodity Supplemental Food Program (CSFP) as a USDA food assistance program. This identity link points to the separately stored USDA CSFP criteria record; it does not extend the partial age mapping or resolve state, tribal, or local rules.","criteria_record_id":"usda-csfp"}],"reviewed_at":"2026-11-06T08:44:02Z","policy_version":"scenario-mapped-criteria-links-v1"}}'::jsonb, '{"source_id":"usagov.benefits","effective_at":null,"retrieved_at":"2026-10-28T19:42:37Z","source_version":"Official USA.gov pages reviewed 2026-10-28; visible page revision dates retained where available.","field_provenance":{"listing.title":{"source_url":"https://www.usa.gov/senior-food-programs","observed_at":"2026-10-28T19:42:37Z","extraction_method":"operator_review"},"listin