INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fna-csfp-published-criteria', 'fna-csfp-2026-income-3', 'federal-program-criteria-reference', '{"eligibility.program.title":"Commodity Supplemental Food Program (CSFP) — 2026 income guideline table","eligibility.program.program_id":"usda-csfp","eligibility.program.data_origin":"Official USDA FNA source reviewed 2026-10-28: https://fns-prod.azureedge.us/csfp/income-guidelines; source statements are partial and non-executable.","eligibility.program.description":"Official 2026 household-income reference table for Hawaii. State/ITO actual income limits may be lower than the federal 150% ceiling; values are preserved as published and not compiled as executable rules.","eligibility.program.catalog_version":"usda-fna-2026-reviewed-2026-10-28","eligibility.program.published_requirements":[{"source_id":"usda.fna.senior-food","statement":"2026 CSFP table for Hawaii; 1: 100% FPG annual $18,360; 130% FPG annual $23,868, monthly $1,989, weekly $459; 150% FPG annual $27,540, monthly $2,295, weekly $530. These are published reference values, not a state-specific limit or eligibility determination.","mapping_status":"not_mapped","requirement_id":"income_table_1"},{"source_id":"usda.fna.senior-food","statement":"2026 CSFP table for Hawaii; 2: 100% FPG annual $24,890; 130% FPG annual $32,357, monthly $2,697, weekly $623; 150% FPG annual $37,335, monthly $3,112, weekly $718. These are published reference values, not a state-specific limit or eligibility determination.","mapping_status":"not_mapped","requirement_id":"income_table_2"},{"source_id":"usda.fna.senior-food","statement":"2026 CSFP table for Hawaii; 3: 100% FPG annual $31,420; 130% FPG annual $40,846, monthly $3,404, weekly $786; 150% FPG annual $47,130, monthly $3,928, weekly $907. These are published reference val