INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fna-csfp-published-criteria', 'fna-csfp-general-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"Commodity Supplemental Food Program (CSFP)","eligibility.program.program_id":"usda-csfp","eligibility.program.data_origin":"Official USDA FNA source reviewed 2026-10-28: https://fns-prod.azureedge.us/csfp/factsheet; source statements are partial and non-executable.","eligibility.program.description":"USDA FNA describes CSFP as monthly USDA Foods support for qualifying low-income people age 60 and older. State/ITO rules and local service-area availability vary; published statements below are not executable criteria.","eligibility.program.catalog_version":"usda-fna-2026-reviewed-2026-10-28","eligibility.program.published_requirements":[{"source_id":"usda.fna.senior-food","statement":"Participants must be at least 60 years of age.","mapping_status":"not_mapped","requirement_id":"minimum_age"},{"source_id":"usda.fna.senior-food","statement":"State agencies and Indian Tribal Organizations set household income limits at or below 150% of the Federal Poverty Guidelines; an agency may set a lower limit. The 2026 annual table is published separately by geography and household size.","mapping_status":"not_mapped","requirement_id":"income_ceiling"},{"source_id":"usda.fna.senior-food","statement":"A state agency or Indian Tribal Organization may set local residency requirements based on designated service areas, but may not require a minimum period of residency.","mapping_status":"not_mapped","requirement_id":"local_residency"},{"source_id":"usda.fna.senior-food","statement":"A state agency or Indian Tribal Organization may require participants to be at nutritional risk, as determined by a physician or local agency staff.","mapping_status":"not_mapped","requirement_id":"nutritional_risk"},{"source_id":"usda.fna.senior-food","statement":"CSFP may not be available in every area within a participating state; applicants must verify local availability with the state distributing agency or local agency.","mapping_status":"context_only","requirement_id":"local_availability"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"national","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","assistance_listing_ids":["10.565"],"assistance_listing_crosswalk":{"basis":"curated_source_crosswalk","reviewed_at":"2026-10-28","evidence_urls":["https://www.usaspending.gov/award/ASST_NON_213CO033J8003_12F2","https://www.fns.usda.gov/csfp/factsheet"]}}'::jsonb, '{"source_id":"usda.fna.senior-food","effective_at":null,"retrieved_at":"2026-10-28T20:04:44Z","source_version":"USDA FNA 2026 CSFP income guidelines issued 2026-02-10; page updated 2026-02-17; reviewed 2026-10-28","field_provenance":{"eligibility.program.title":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://fns-prod.azureedge.us/csfp/factsheet","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"}},"transform_version":"fna-senior-food-criteria-review-v1","raw_payload_stored":false}'::jsonb, 'https://fns-prod.azureedge.us/csfp/factsheet', 'd4245002848bb66b8dbb431317a0b44e7e428feba8052f0c9d3a3e6131c7692f', 'eligibility-program-v2', '2026-10-28T20:04:44+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fna-sfmnp-published-criteria', 'fna-sfmnp-general-criteria-2026', 'federal-program-criteria-reference', '{"eligibility.program.title":"Senior Farmers Market Nutrition Program (SFMNP)","eligibility.program.program_id":"usda-sfmnp","eligibility.program.data_origin":"Official USDA FNA source reviewed 2026-10-28: https://www.fna.usda.gov/sfmnp; source statements are partial and non-executable.","eligibility.program.description":"USDA FNA describes SFMNP as support for low-income seniors through state-administered farmers market programs. The federal page gives a general age/income description and points to current 2026-2027 guidelines; state participation and actual rules must be checked.","eligibility.program.catalog_version":"usda-fna-2026-reviewed-2026-10-28","eligibility.program.published_requirements":[{"source_id":"usda.fna.senior-food","statement":"USDA FNA generally defines low-income seniors served by SFMNP as individuals at least 60 years old. State program rules should be checked.","mapping_status":"not_mapped","requirement_id":"minimum_age"},{"source_id":"usda.fna.senior-food","statement":"USDA FNA generally describes SFMNP as serving seniors with household income not more than 185% of the Federal Poverty Guidelines. This general description does not replace the current participating state agency rules.","mapping_status":"not_mapped","requirement_id":"income_guideline"},{"source_id":"usda.fna.senior-food","statement":"SFMNP operates through state, territory, and tribal administering agencies; availability must be verified for the applicant jurisdiction and local program.","mapping_status":"context_only","requirement_id":"state_participation"},{"source_id":"usda.fna.senior-food","statement":"USDA FNA lists 2026-2027 SFMNP Income Eligibility Guidelines, published 2026-04-10. The linked guideline body/table was not available for direct extraction in this review; no household-size dollar amounts are asserted in this record.","mapping_status":"context_only","requirement_id":"current_guideline_reference"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"national","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","assistance_listing_ids":["10.576"],"assistance_listing_crosswalk":{"basis":"curated_source_crosswalk","reviewed_at":"2026-10-28","evidence_urls":["https://www.usaspending.gov/award/ASST_NON_235GA720I4003_012","https://www.fns.usda.gov/sfmnp/senior-farmers-market-nutrition-program-sfmnp"]}}'::jsonb, '{"source_id":"usda.fna.senior-food","effective_at":null,"retrieved_at":"2026-10-28T20:04:44Z","source_version":"USDA FNA SFMNP program page updated 2026-04-22 and 2026-2027 income guideline memo published 2026-04-10; reviewed 2026-10-28","field_provenance":{"eligibility.program.title":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://www.fna.usda.gov/sfmnp","observed_at":"2026-10-28T20:04:44Z","extraction_method":"operator_review"}},"transform_version":"fna-senior-food-criteria-review-v1","raw_payload_stored":false}'::jsonb, 'https://www.fna.usda.gov/sfmnp', '06466771a1c53d4e7ba86e63058a39f2f17a1e94b2cf9dea558eb12cc91e4120', 'eligibility-program-v2', '2026-10-28T20:04:44+00:00') ON CONFLICT DO NOTHING;
