INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fsa-farm-loan-published-criteria', 'fsa-beginning-farmer-classification-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"FSA Beginning Farmer classification requirements","eligibility.program.navigator":"farm_business","eligibility.program.program_id":"fsa-beginning-farmer-classification","eligibility.program.data_origin":"USDA FSA Beginning Farmers and Ranchers Loans page","eligibility.program.description":"FSA describes beginning-farmer classification as a targeted funding source, with the Direct Farm Ownership Down Payment Loan as the exception where it is a loan-program requirement. Acreage calculations and loan-specific requirements need additional profile and source data.","eligibility.program.catalog_version":"retrieved-2026-10-28","eligibility.program.published_requirements":[{"unit":"years","value":10,"operator":"lte","attribute":"core.farm_business.years_farming","source_id":"usda.fsa.beginning-farmers","statement":"A beginning farmer has not operated a farm or ranch for more than 10 years.","concept_id":"eligibility.fsa.beginning_farmer.years_operated","mapping_status":"mapped","requirement_id":"farm-operation-years","requirement_type":"eligibility"},{"source_id":"usda.fsa.beginning-farmers","statement":"A beginning farmer does not own a farm or ranch greater than 30 percent of the average size farm in the county, using the most current Census of Agriculture when the loan application is submitted.","mapping_status":"not_mapped","requirement_id":"county-farm-ownership-limit"},{"source_id":"usda.fsa.beginning-farmers","statement":"A beginning farmer substantially participates in the operation.","mapping_status":"not_mapped","requirement_id":"substantial-participation"},{"source_id":"usda.fsa.beginning-farmers","statement":"A beginning farmer must also meet the eligibility requirements of the specific Farm Operating Loan, Farm Ownership Loan, or Microloan being requested.","mapping_status":"not_mapped","requirement_id":"loan-specific-requirements"},{"source_id":"usda.fsa.beginning-farmers","statement":"When a farm crosses county lines, FSA uses the applicant''s residence county; if the residence is not on the farm, it uses the county containing the largest portion of the farm.","mapping_status":"context_only","requirement_id":"county-selection-rule"},{"source_id":"usda.fsa.beginning-farmers","statement":"FSA says the farm-acreage limitation does not apply to a member of a historically underserved group or a woman farmer.","mapping_status":"not_mapped","requirement_id":"acreage-exception"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_source_links":[{"basis":"curated_source_crosswalk","source":{"url":"https://www.farmers.gov/blog/ask-expert-qa-on-usda-beginning-farmers-with-sarah-campbell","title":"Ask the Expert: A Q&A on USDA Beginning Farmers with Sarah Campbell","agency":"USDA Farm Production and Conservation, Farmers.gov","source_id":"public-domain.gov","source_type":"public_source","jurisdiction":{"level":"federal","state_code":null,"county_name":null,"country_code":"US"},"retrieved_at":"2026-11-10T06:02:56.496041Z","effective_date":null,"approval_status":"unverified","contract_version":"source-reference-v1","publisher_version":"sha256:6d50b3ade11fc5ea615eb2f074caa8850229934f4a0ad8fb32252b606d6c6344"},"reviewed_at":"2026-11-10T06:02:56.496041Z","evidence_urls":["https://www.farmers.gov/blog/ask-expert-qa-on-usda-beginning-farmers-with-sarah-campbell","[internal issue reference]#issuecomment-6760393661","[internal issue reference]#issuecomment-6761440140"]}],"assistance_listing_ids":["10.407"],"assistance_listing_crosswalk":{"basis":"curated_source_crosswalk"