INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fsa-farm-loan-published-criteria', 'fsa-direct-farm-loan-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"FSA Direct Farm Loan published requirements","eligibility.program.navigator":"farm_business","eligibility.program.program_id":"usda-fsa-direct-farm-loans","eligibility.program.data_origin":"USDA FSA Farm Loan Programs page","eligibility.program.description":"FSA describes broad farm-loan access conditions and additional direct-loan repayment and collateral requirements. The source does not provide an applicant-specific determination.","eligibility.program.catalog_version":"retrieved-2026-10-28","eligibility.program.published_requirements":[{"source_id":"usda.fsa.beginning-farmers","statement":"FSA''s direct and guaranteed farm ownership and operating loans serve family-size farmers and ranchers.","mapping_status":"not_mapped","requirement_id":"family-size-farm"},{"source_id":"usda.fsa.beginning-farmers","statement":"The Farm Loan Programs page describes these loans for family-size farmers and ranchers who cannot obtain commercial credit from a bank, Farm Credit System institution, or other lender.","mapping_status":"not_mapped","requirement_id":"commercial-credit-unavailable"},{"source_id":"usda.fsa.beginning-farmers","statement":"A direct-loan applicant must show sufficient repayment ability.","mapping_status":"not_mapped","requirement_id":"direct-repayment-ability"},{"source_id":"usda.fsa.beginning-farmers","statement":"A direct-loan applicant must pledge enough collateral to fully secure the loan.","mapping_status":"not_mapped","requirement_id":"direct-collateral"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","a