INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('usda-fsa-farm-loan-published-criteria', 'fsa-guaranteed-farm-loan-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"FSA Guaranteed Farm Loan published requirements","eligibility.program.navigator":"farm_business","eligibility.program.program_id":"usda-fsa-guaranteed-farm-loan","eligibility.program.data_origin":"USDA FSA Guaranteed Farm Loans page","eligibility.program.description":"Partial source-backed statements for the FSA guarantee pathway. The guarantee is arranged through a commercial lender; program exceptions and additional facts remain unresolved.","eligibility.program.catalog_version":"retrieved-2026-10-28","eligibility.program.published_requirements":[{"source_id":"usda.fsa.beginning-farmers","statement":"The applicant must be a United States citizen or legal resident alien.","mapping_status":"not_mapped","requirement_id":"citizenship-or-residency"},{"source_id":"usda.fsa.beginning-farmers","statement":"The applicant must have an acceptable credit history as determined by the lender.","mapping_status":"not_mapped","requirement_id":"acceptable-credit-history"},{"source_id":"usda.fsa.beginning-farmers","statement":"The applicant must have legal capacity to incur responsibility for the loan obligation.","mapping_status":"not_mapped","requirement_id":"legal-capacity"},{"source_id":"usda.fsa.beginning-farmers","statement":"The applicant must be unable to obtain a loan without an FSA guarantee, except that the page states Conservation Loan applicants do not have to meet this condition.","mapping_status":"not_mapped","requirement_id":"guarantee-needed-for-credit"},{"source_id":"usda.fsa.beginning-farmers","statement":"The applicant must not be delinquent on any Federal debt.","mapping_status":"not_mapped","requirement_id":"federal-debt-status"},{"source_id":"usda.fsa.beginning-farmers","statement":"After loan closing, the applicant must be the owner-operator or tenant-operator of a family farm; for Farm Ownership loans the producer also needs to own the farm.","mapping_status":"not_mapped","requirement_id":"farm-operator-role"},{"source_id":"usda.fsa.beginning-farmers","statement":"A farmer interested in a guaranteed loan applies to a conventional lender, which arranges the FSA guarantee.","mapping_status":"context_only","requirement_id":"application-through-lender"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","assistance_listing_ids":["10.406","10.407"],"assistance_listing_crosswalk":{"basis":"curated_source_crosswalk","reviewed_at":"2026-10-29","evidence_urls":["https://www.fsa.usda.gov/about-fsa/structure-organization/farm-loan-programs","https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","https://sam.gov/fal/a1dc2ed6a9d94121b59a155149bc8d28/view","https://sam.gov/fal/114c57552fdc4821a849fcf0003fe089/view"]}}'::jsonb, '{"source_id":"usda.fsa.beginning-farmers","effective_at":null,"retrieved_at":"2026-10-28T17:38:02Z","source_version":"Current official FSA beginning-farmer, ownership, loan-program, and guaranteed-loan pages reviewed 2026-10-28; publisher revision dates not stated.","field_provenance":{"eligibility.program.title":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans","observed_at":"2026-10-28T17:38:02Z","extraction_method":"operator_review"}},"transform_version":"fsa-farm-loan-criteria-review-v3","raw_payload_stored":false}'::jsonb, 'https://www.fsa.usda.gov/resources/loans/guaranteed-farm-loans', 'b63eb0b8830808558348a1402f4c40dfb755e61651d62158236201a24eb60363', 'eligibility-program-v3', '2026-10-28T17:38:02+00:00') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('va-aid-attendance-mapped-criteria', 'va-aid-attendance-housebound', 'eligibility_program', '{"eligibility.program.title":"VA Aid and Attendance and Housebound allowance (partial screening criteria)","core.geography.country_code":"US","eligibility.program.details":[{"kind":"application_step","text":"You can apply for VA Aid and Attendance or Housebound benefits online, by mail, or in person.","source_id":"us.va.public-benefits"},{"kind":"form","text":"If you are in a nursing home, also fill out VA Form 21-0779, Request for Nursing Home Information in Connection with Claim for Aid and Attendance.","source_id":"us.va.public-benefits"},{"kind":"form","text":"For a mail application, fill out VA Form 21-2680, Examination for Housebound Status or Permanent Need for Regular Aid and Attendance.","source_id":"us.va.public-benefits"},{"kind":"application_step","text":"A medical examiner must fill out the examination information section for an online or mail application.","source_id":"us.va.public-benefits"},{"kind":"application_step","text":"Mail the completed form to the Department of Veterans Affairs Pension Intake Center, PO Box 5365, Janesville, WI 53547-5365.","source_id":"us.va.public-benefits"},{"kind":"application_step","text":"For an in-person application, bring your information to a nearby VA regional office.","source_id":"us.va.public-benefits"}],"eligibility.program.criteria":[{"value":"receiving","operator":"eq","attribute":"core.person.va_pension_status","source_id":"us.va.public-benefits","criterion_id":"va-pension-prerequisite"},{"value":true,"operator":"eq","attribute":"core.person.daily_care_need","source_id":"us.va.public-benefits","criterion_id":"va-aid-attendance-daily-assistance"}],"eligibility.program.navigator":"senior_caregiver","eligibility.program.program_id":"va-aid-attendance-housebound","eligibility.program.data_origin":"public_source","eligibility.program.description":"Partial screening of the published VA pension prerequisite and Aid and Attendance daily-assistance condition. Other Aid and Attendance alternatives, Housebound conditions, and VA adjudication are not evaluated.","core.geography.jurisdiction_level":"federal","eligibility.program.catalog_version":"va-aid-attendance-reviewed-2026-11-03"}'::jsonb, '{"record_role":"program_listing","jurisdiction":{"level":"federal","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial","criteria_mapping_review":{"reviewed_at":"2026-11-03T19:49:50Z","source_content_sha256":"5718b8d7fdebc049383aea336f75c199b9fb75ce829aa56bbafa320f01d9c385","mapped_requirement_ids":["va-pension-prerequisite","aid-attendance-alternative-1"],"unresolved_requirement_ids":["aid-attendance-alternative-2","aid-attendance-alternative-3","aid-attendance-alternative-4","housebound-criterion","mutually-exclusive-allowances"]}}'::jsonb, '{"publisher":"U.S. Department of Veterans Affairs","source_id":"us.va.public-benefits","limitations":["This record compares only VA pension receipt and the daily-assistance condition.","The other Aid and Attendance alternatives (bed rest, nursing-home status, and eyesight thresholds) are not evaluated.","Housebound permanence/time-at-home conditions and mutually exclusive allowances are not evaluated.","VA adjudicates complete eligibility; this screening output is not a determination."],"source_type":"public_source","content_hash":"d49ba279646e39e4edeb1a2ce7aae4a30276bfee25e880a31773084029ec5efb","retrieved_at":"2026-11-09T04:51:31.259814Z","source_title":"Aid and Attendance benefits and Housebound allowance","effective_date":null,"source_version":"sha256:6508d089fcf5f5543b15ae2ee78a299791f9191910844f0aa968967b6be2a1aa","approval_status":"approved","field_provenance":{"eligibility.program.title":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"core.geography.country_code":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.details":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-09T04:51:31.259814Z","extraction_method":"operator_review"},"eligibility.program.criteria":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.navigator":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"core.geography.jurisdiction_level":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-11-03T19:49:50Z","extraction_method":"operator_review"}},"criteria_coverage":"partial","transform_version":"va-aid-attendance-mapped-criteria-v2","raw_payload_stored":false,"source_content_sha256":"6508d089fcf5f5543b15ae2ee78a299791f9191910844f0aa968967b6be2a1aa"}'::jsonb, 'https://www.va.gov/pension/aid-attendance-housebound/', 'd49ba279646e39e4edeb1a2ce7aae4a30276bfee25e880a31773084029ec5efb', 'eligibility-program-v4', '2026-11-09T04:51:31.259814+00:00') ON CONFLICT DO NOTHING;
