INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('va-caregiver-published-criteria', 'va-aid-attendance-housebound-published-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"Aid and Attendance and Housebound published criteria","eligibility.program.program_id":"va-aid-attendance-housebound","eligibility.program.data_origin":"Aid and Attendance and Housebound published criteria official VA.gov page; statements are partial and non-executable.","eligibility.program.description":"Official VA published conditions; pension rules and detailed evidence are not fully represented. Statements remain unmapped and non-executable.","eligibility.program.catalog_version":"va-reviewed-2026-10-29","eligibility.program.published_requirements":[{"source_id":"us.va.public-benefits","statement":"The applicant must receive a VA pension.","mapping_status":"not_mapped","requirement_id":"va-pension-prerequisite"},{"source_id":"us.va.public-benefits","statement":"The applicant needs another person to help with daily activities such as bathing, feeding, and dressing.","mapping_status":"not_mapped","requirement_id":"aid-attendance-alternative-1"},{"source_id":"us.va.public-benefits","statement":"The applicant must stay in bed, or spend a large portion of the day in bed, because of illness.","mapping_status":"not_mapped","requirement_id":"aid-attendance-alternative-2"},{"source_id":"us.va.public-benefits","statement":"The applicant is a nursing-home patient due to loss of mental or physical abilities related to a disability.","mapping_status":"not_mapped","requirement_id":"aid-attendance-alternative-3"},{"source_id":"us.va.public-benefits","statement":"The applicant has eyesight limited to 5/200 or less in both eyes, or visual-field contraction to 5 degrees or less, even with correction.","mapping_status":"not_mapped","requirement_id":"aid-attendance-alternative-4"},{"source_id":"us.va.public-benefits","statement":"The applicant receives a VA pension and spends most of their time at home because of a permanent disability.","mapping_status":"not_mapped","requirement_id":"housebound-criterion"},{"source_id":"us.va.public-benefits","statement":"Aid and Attendance and Housebound benefits cannot be received at the same time.","mapping_status":"not_mapped","requirement_id":"mutually-exclusive-allowances"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"national","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial"}'::jsonb, '{"source_id":"us.va.public-benefits","effective_at":null,"retrieved_at":"2026-10-29T13:22:00Z","source_version":"VA.gov PCAFC and Aid and Attendance/Housebound pages reviewed 2026-10-29; no publisher revision date recorded.","field_provenance":{"eligibility.program.title":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://www.va.gov/pension/aid-attendance-housebound/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"}},