INSERT INTO mcp_saas.public_dataset_records (dataset_id, source_record_id, record_type, canonical_attributes, semantic_context, source_metadata, source_url, content_hash, schema_version, observed_at) VALUES ('va-caregiver-published-criteria', 'va-pcafc-published-criteria', 'federal-program-criteria-reference', '{"eligibility.program.title":"PCAFC published eligibility criteria","eligibility.program.program_id":"va-pcafc","eligibility.program.data_origin":"PCAFC published eligibility criteria official VA.gov page; statements are partial and non-executable.","eligibility.program.description":"Official VA caregiver criteria statements; multiple conditions and assessment remain partial, unmapped, and non-executable.","eligibility.program.catalog_version":"va-reviewed-2026-10-29","eligibility.program.published_requirements":[{"source_id":"us.va.public-benefits","statement":"The family caregiver must be at least 18 years old.","mapping_status":"not_mapped","requirement_id":"caregiver-age"},{"source_id":"us.va.public-benefits","statement":"The caregiver must be a spouse, son, daughter, parent, stepfamily member, extended family member, or live full time with the Veteran or be willing to do so if designated.","mapping_status":"not_mapped","requirement_id":"caregiver-relationship-or-co-residence"},{"source_id":"us.va.public-benefits","statement":"The Veteran must have an individual or combined VA disability rating of 70% or higher.","mapping_status":"not_mapped","requirement_id":"veteran-disability-rating"},{"source_id":"us.va.public-benefits","statement":"The Veteran must have been discharged from the U.S. military or have a date of medical discharge.","mapping_status":"not_mapped","requirement_id":"veteran-discharge"},{"source_id":"us.va.public-benefits","statement":"The Veteran must need at least 6 months of continuous, in-person personal care services.","mapping_status":"not_mapped","requirement_id":"personal-care-duration"},{"source_id":"us.va.public-benefits","statement":"The Veteran must be enrolled in VA health care.","mapping_status":"not_mapped","requirement_id":"va-health-care-enrollment"},{"source_id":"us.va.public-benefits","statement":"The Veteran and caregiver apply together; VA conducts an application and assessment process.","mapping_status":"context_only","requirement_id":"joint-application-and-assessment"}]}'::jsonb, '{"record_role":"criteria","jurisdiction":{"level":"national","country_code":"US"},"catalog_namespace":"programs","criteria_coverage":"partial"}'::jsonb, '{"source_id":"us.va.public-benefits","effective_at":null,"retrieved_at":"2026-10-29T13:22:00Z","source_version":"VA.gov PCAFC and Aid and Attendance/Housebound pages reviewed 2026-10-29; no publisher revision date recorded.","field_provenance":{"eligibility.program.title":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.program_id":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.data_origin":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.description":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.catalog_version":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"},"eligibility.program.published_requirements":{"source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","observed_at":"2026-10-29T13:22:00Z","extraction_method":"operator_review"}},"transform_version":"va-veteran-caregiver-review-v1","raw_payload_stored":false}'::jsonb, 'https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/', '93c84631b2bccf184733a60c8ca95972602e24502fe5ae989ee9bc09423fdc04', 'eligibility-program-v2', '2026-10-29T13:22:00+00:00') ON CONFLICT DO NOTHING;
