INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('codex-e2e-20261113-s7', 'd8574b5e3f094d7ddbd67aafb65a71b02e061bef5d6eca33c5e6a1408fa24362', '{"title":"Missouri Temporary Assistance (partial screening criteria)","navigator":"low_income_assistance","program_id":"codex-e2e-20261113-s7","requirements":[{"citation":{"excerpt":"Temporary Assistance (TA) is a cash benefit for low-income families to help cover costs for the household’s children, such as clothing, utilities and other services. Once you are approved for TA, you must participate in employment and training services through the Missouri Work Assistance (MWA) Program . This program will help you move away from needing cash benefits through TA by setting goals and helping you get the skills you need to find a job to support your family.","locator":"html.visible_text","source_id":"missouri.dss.temporary-assistance","source_url":"https://dss.mo.gov/temporary-assistance/apply","retrieved_at":"2026-11-13T23:27:19.661314Z","source_version":"sha256:7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_record_id":"source-page-63ef48e56e04eb5ad105","source_content_sha256":"7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_visible_text_sha256":"6985487725bf502e4c8b423359419cc600a04a9df6439dec894237a87c73f980"},"statement":"Temporary Assistance (TA) is a cash benefit for low-income families to help cover costs for the household’s children, such as clothing, utilities and other services. Once you are approved for TA, you must participate in employment and training services through the Missouri Work Assistance (MWA) Program . This program will help you move away from needing cash benefits through TA by setting goals and helping you get the skills you need to find a job to support your family.","mapping_status":"context_only","requirement_id":"codex-s7-1","requirement_type":"context"},{"citation":{"excerpt":"You may be eligible for help if you are the parent or guardian of a child under age 18 (unless the child is in high school and expected to graduate before age 19) and you:","locator":"html.visible_text","source_id":"missouri.dss.temporary-assistance","source_url":"https://dss.mo.gov/temporary-assistance/apply","retrieved_at":"2026-11-13T23:27:19.661314Z","source_version":"sha256:7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_record_id":"source-page-63ef48e56e04eb5ad105","source_content_sha256":"7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_visible_text_sha256":"6985487725bf502e4c8b423359419cc600a04a9df6439dec894237a87c73f980"},"statement":"You may be eligible for help if you are the parent or guardian of a child under age 18 (unless the child is in high school and expected to graduate before age 19) and you:","mapping_status":"not_mapped","requirement_id":"codex-s7-2","requirement_type":"eligibility","unresolved_reason":"Requires facts or compound semantics unavailable in the reviewed typed profile; retained as unresolved."},{"value":"MO","citation":{"excerpt":"Live in Missouri","locator":"html.visible_text","source_id":"missouri.dss.temporary-assistance","source_url":"https://dss.mo.gov/temporary-assistance/apply","retrieved_at":"2026-11-13T23:27:19.661314Z","source_version":"sha256:7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_record_id":"source-page-63ef48e56e04eb5ad105","source_content_sha256":"7810731801f3a08c317a3b2892cd30aa7556b7c8cd742dcfd58f2f1feee8d39f","source_visible_text_sha256":"6985487725bf502e4c8b423359419cc600a04a9df6439dec894237a87c73f980"},"operator":"eq","statement":"Live in Missouri","concept_id":"core.geography.state_code","mapping_status":"mapped","requirement_id":"codex-s7-3","requirement_type":"eligibility","profile_attribute":"core.geography.state_code"},{"citation":{"excerpt":"Do not own resources worth more than $1,000 (except your home and one vehicle)","loc