lity","unresolved_reason":"Requires unsupported fact, external limits or case-specific exclusions."},{"citation":{"excerpt":"- Do not make more than the current income limit","locator":"html.visible_text: paragraph 10","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-14T15:47:07.201323Z","source_version":"sha256:1ee66276dc620e82c3a495f109330e36d6c2333a1d53cdbd49377a8ca0fcf9e6","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"1ee66276dc620e82c3a495f109330e36d6c2333a1d53cdbd49377a8ca0fcf9e6","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Do not make more than the current income limit","mapping_status":"not_mapped","requirement_id":"req-465fe3d834cfcf9c55943592","requirement_type":"eligibility","unresolved_reason":"Requires unsupported fact, external limits or case-specific exclusions."},{"citation":{"excerpt":"- Do not own more than $3,000 in resources ($4,750 if at least one member of your household is over the age of 60 or disabled)","locator":"html.visible_text: paragraph 11","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-14T15:47:07.201323Z","source_version":"sha256:1ee66276dc620e82c3a495f109330e36d6c2333a1d53cdbd49377a8ca0fcf9e6","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"1ee66276dc620e82c3a495f109330e36d6c2333a1d53cdbd49377a8ca0fcf9e6","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Do not own more than $3,000 in resources ($4,750 if at least one member of your household is over the age of 60 or disabled)","mapping_status":"not_mapped","requirement_id":"req-b6e71f67eeae005b7ce6bace","requirement_type":"eligibility","unresolved_reason":"Requires unsupported fact, external limits or case-specific exclusions."},{"citation":{"excerpt":