INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('desktop-e2e-1114-s5', 'e467523be89740bbc0edf2ca791fda56578c992efb81ede00a2a14d6dc0af642', '{"title":"VA Aid and Attendance and Housebound allowance","navigator":"senior_caregiver","program_id":"desktop-e2e-1114-s5","requirements":[{"value":"receiving","citation":{"excerpt":"You may be eligible for this benefit if you get a VA pension and you meet at least 1 of these requirements.","locator":"html.visible_text: paragraph 7","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"operator":"eq","statement":"You may be eligible for this benefit if you get a VA pension and you meet at least 1 of these requirements.","concept_id":"core.person.va_pension_status","mapping_status":"mapped","requirement_id":"req-4d61e0b471f1fa606dafdc17","requirement_type":"eligibility","profile_attribute":"va_pension_status"},{"value":true,"citation":{"excerpt":"- You need another person to help you perform daily activities, like bathing, feeding, and dressing, or","locator":"html.visible_text: paragraph 9","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"operator":"eq","statement":"You need another person to help you perform daily activities, like bathing, feeding, and dressing, or","concept_id":"core.person.daily_care_need","logic_group_id":"aid-attendance-alternatives","mapping_status":"mapped","requirement_id":"req-3b1acc3e3133117963c88b0b","requirement_type":"eligibility","profile_attribute":"daily_care_need","logic_group_operator":"any_of"},{"citation":{"excerpt":"- You have to stay in bed—or spend a large portion of the day in bed—because of illness, or","locator":"html.visible_text: paragraph 10","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"You have to stay in bed—or spend a large portion of the day in bed—because of illness, or","logic_group_id":"aid-attendance-alternatives","mapping_status":"not_mapped","requirement_id":"req-59bcffa056b32747e9bd97ba","requirement_type":"eligibility","unresolved_reason":"Unsupported alternative or compound condition; retained unknown.","logic_group_operator":"any_of"},{"citation":{"excerpt":"- You’re a patient in a nursing home due to the loss of mental or physical abilities related to a disability, or","locator":"html.visible_text: paragraph 11","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"You’re a patient in a nursing home due to the loss of mental or physical abilities related to a disability, or","logic_group_id":"aid-attendance-alternatives","mapping_status":"not_mapped","requirement_id":"req-f65ef7ee6dcf73560106e3aa","requirement_type":"eligibility","unresolved_reason":"Unsupported alternative or compound condition; retained unknown.","logic_group_operator":"any_of"},{"citation":{"excerpt":"- Your eyesight is limited (even with glasses or contact lenses you have only 5/200 or less in both eyes; or concentric contraction of the visual field to 5 degrees or less)","locator":"html.visible_text: paragraph 12","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"Your eyesight is limited (even with glasses or contact lenses you have only 5/200 or less in both eyes; or concentric contraction of the visual field to 5 degrees or less)","logic_group_id":"aid-attendance-alternatives","mapping_status":"not_mapped","requirement_id":"req-2cc63661b1a0442f7c19c57a","requirement_type":"eligibility","unresolved_reason":"Unsupported alternative or compound condition; retained unknown.","logic_group_operator":"any_of"},{"citation":{"excerpt":"You may be eligible for this benefit if you get a VA pension and you spend most of your time in your home because of a permanent disability (a disability that doesn’t go away).","locator":"html.visible_text: paragraph 14","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"You may be eligible for this benefit if you get a VA pension and you spend most of your time in your home because of a permanent disability (a disability that doesn’t go away).","mapping_status":"not_mapped","requirement_id":"req-4f3d1492533147a7cd8b8730","requirement_type":"eligibility","unresolved_reason":"Unsupported alternative or compound condition; retained unknown."},{"citation":{"excerpt":"Note: You can’t get Aid and Attendance benefits and Housebound benefits at the same time.","locator":"html.visible_text","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46:47.215628Z","source_version":"sha256:c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"c73a0b46cd54b1ac7fd03d6f2a84ae6125ef426936f6453354d707d037ea3acc","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"Note: You can’t get Aid and Attendance benefits and Housebound benefits at the same time.","mapping_status":"context_only","requirement_id":"va-mutual-exclusion","requirement_type":"context"}],"compiled_rules":[{"citation":{"excerpt":"You may be eligible for this benefit if you get a VA pension and you meet at least 1 of these requirements.","locator":"html.visible_text: paragraph 7","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-14T15:46: