INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('desktop-e2e-1114-s9', 'f36c76b017abc61e31c244addad738eab634d1f61195997fa067ba090f64d42a', '{"title":"Kansas Food Assistance residency guidance (partial criteria)","navigator":"low_income_assistance","program_id":"desktop-e2e-1114-s9","requirements":[{"value":"KS","citation":{"excerpt":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","locator":"html.visible_text","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-14T15:48:01.538873Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"operator":"eq","statement":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","concept_id":"core.geography.state_code","mapping_status":"mapped","requirement_id":"kansas-food-residency","requirement_type":"eligibility","profile_attribute":"state_code"},{"citation":{"excerpt":"2151 Duplicate Benefits - Residence can be established in a month regardless of whether the person has received benefits from another state in that month. However for cash and food assistance purposes, benefits cannot be provided in any month in which the client has received such benefits in another state.","locator":"html.visible_text","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-14T15:48:01.538873Z","sour