","jurisdiction":{"level":"state","state_code":"KS","country_code":"US"},"retrieved_at":"2026-11-14T15:48:01.538873Z","approval_status":"unverified","authority_class":"unverified","observed_at_utc":"2026-11-14T15:48:01.538873+00:00","contract_version":"source-reference-v1","publisher_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_verification_status":"unverified","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"}],"criteria_package_id":"criteria-e48a264884a314976ee201e828ea9080","profile_schema_refs":[{"registry_id":"core-schema-registry","schema_version":"core-v1"},{"registry_id":"core-schema-registry","schema_version":"core-v2"},{"registry_id":"core-schema-registry","schema_version":"core-v3"},{"registry_id":"core-schema-registry","schema_version":"core-v4"},{"registry_id":"core-schema-registry","schema_version":"core-v5"},{"registry_id":"core-schema-registry","schema_version":"core-v6"},{"registry_id":"core-schema-registry","schema_version":"core-v7"},{"registry_id":"core-schema-registry","schema_version":"core-v8"}]}'::jsonb, '2026-11-14T16:01:18.772747+00:00', 'eligibility') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('fsa-beginning-farmer-classification', '90545e22d40fb5982cfe877f807cc8e6ea39f00a6778124f11b23b1df6d86f95', '{"title":"FSA Beginning Farmer classification requirements","navigator":"farmer_producer","program_id":"fsa-beginning-farmer-classification","requirements":[{"unit":"years","value":10,"citation":{"excerpt":"Has not operated a farm or ranch for more than 10 years","locator":"html.visible_text: Beginning Farmer Definition","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"operator":"lte","statement":"A beginning farmer has not operated a farm or ranch for more than 10 years.","concept_id":"eligibility.fsa.beginning_farmer.years_operated","criterion_id":"farm-operation-years","mapping_status":"mapped","requirement_id":"farm-operation-years","requirement_type":"eligibility","profile_attribute":"core.farm_business.years_farming"},{"citation":{"excerpt":"Does not own more than 30 percent of the average size farm in the county","locator":"html.visible_text: Farm Acreage Limitations","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"statement":"A beginning farmer does not own a farm or ranch greater than 30 percent of the average size farm in the county, using the most current Census of Agriculture when the loan application is submitted.","mapping_status":"not_mapped","requirement_id":"county-farm-ownership-limit","requirement_type":"eligibility","unresolved_reason":"Requires owned acreage, applicable county, and current Census farm-size value."},{"citation":{"excerpt":"Substantially participates in the operation","locator":"html.visible_text: Beginning Farmer Definition","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"statement":"A beginning farmer substantially participates in the operation.","mapping_status":"not_mapped","requirement_id":"substantial-participation","requirement_type":"eligibility","unresolved_reason":"The source phrase requires an operational definition and additional facts."},{"citation":{"excerpt":"Meets the loan eligibility requirements of the program to which the applicant is applying","locator":"html.visible_text: Beginning Farmer Definition","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"statement":"A beginning farmer must also meet the eligibility requirements of the specific Farm Operating Loan, Farm Ownership Loan, or Microloan being requested.","mapping_status":"not_mapped","requirement_id":"loan-specific-requirements","requirement_type":"eligibility","unresolved_reason":"The loan product is not selected and its specific requirements are not mapped."},{"citation":{"excerpt":"FSA uses the county where the applicant lives; if the home is not on the farm, it uses the county containing the largest portion of the farm","locator":"html.visible_text: Farm Acreage Limitations","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"statement":"When a farm crosses county lines, FSA uses the applicant''s residence county; if the residence is not on the farm, it uses the county containing the largest portion of the farm.","mapping_status":"context_only","requirement_id":"county-selection-rule","requirement_type":"context"},{"citation":{"excerpt":"The farm acreage limitation does not apply to a member of an historically underserved group or a woman farmer","locator":"html.visible_text: Farm Acreage Limitations","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"statement":"The farm-acreage limitation does not apply to a member of a historically underserved group or a woman farmer.","mapping_status":"not_mapped","requirement_id":"acreage-exception","requirement_type":"eligibility","unresolved_reason":"Exception application needs required profile facts and mapped criteria context."}],"compiled_rules":[{"citation":{"excerpt":"Has not operated a farm or ranch for more than 10 years","locator":"html.visible_text: Beginning Farmer Definition","source_id":"usda.fsa.beginning-farmers","source_url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","retrieved_at":"2026-11-17T18:17:27.837840Z","source_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_record_id":"fsa-beginning-farmer-classification-criteria","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"},"criterion":{"value":10,"operator":"lte","attribute":"core.farm_business.years_farming","source_id":"usda.fsa.beginning-farmers","criterion_id":"farm-operation-years","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"A beginning farmer has not operated a farm or ranch for more than 10 years.","applicability":null,"requirement_id":"farm-operation-years","threshold_basis":null}],"program_record":{"title":"FSA Beginning Farmer classification requirements","details":[],"sources":[{"url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","title":"Beginning Farmers and Ranchers Loans | Farm Service Agency","agency":"USDA Farm Service Agency","source_id":"usda.fsa.beginning-farmers","source_type":"public_source","jurisdiction":{"level":"federal","state_code":null,"county_name":null,"country_code":"US"},"retrieved_at":"2026-11-17T18:17:27.837840Z","effective_date":null,"approval_status":"approved","contract_version":"source-reference-v1","publisher_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089"}],"criteria":[{"value":10,"operator":"lte","attribute":"core.farm_business.years_farming","source_id":"usda.fsa.beginning-farmers","criterion_id":"farm-operation-years","logic_group_id":null,"context_attribute":null,"logic_group_operator":null}],"navigator":"farmer_producer","program_id":"fsa-beginning-farmer-classification","data_origin":"public_source","description":"FSA beginning-farmer classification; only the source-published 10-year operation criterion is mapped.","jurisdiction":{"level":"federal","state_code":null,"county_name":null,"country_code":"US"},"catalog_version":"retrieved-2026-11-17","contract_version":"eligibility-program-v1","source_limitations":["Only the 10-year beginning-farmer classification criterion is mapped; this is not loan eligibility.","County acreage, substantial participation, exception, and loan-specific clauses remain unresolved or context-only."]},"criteria_status":"partial","contract_version":"eligibility-criteria-ruleset-v1","source_references":[{"url":"https://www.fsa.usda.gov/resources/beginning-farmers-and-ranchers-loans","title":"Beginning Farmers and Ranchers Loans | Farm Service Agency","agency":"USDA Farm Service Agency","source_id":"usda.fsa.beginning-farmers","source_type":"public_source","jurisdiction":{"level":"federal","country_code":"US"},"retrieved_at":"2026-11-17T18:17:27.837840Z","approval_status":"unverified","authority_class":"unverified","observed_at_utc":"2026-11-17T18:17:27.837840+00:00","contract_version":"source-reference-v1","publisher_version":"sha256:602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_content_sha256":"602fe49a3271d1a10d9bb4fe57944c6fdff422f21aa0cadd49d16f46002df089","source_verification_status":"unverified"}],"criteria_package_id":"criteria-445741ec47c8a4125eae21c367c4ff97","profile_schema_refs":[{"registry_id":"core-schema-registry","schema_version":"core-v1"},{"registry_id":"core-schema-registry","schema_version":"core-v2"},{"registry_id":"core-schema-registry","schema_version":"core-v3"},{"registry_id":"core-schema-registry","schema_version":"core-v4"},{"registry_id":"core-schema-registry","schema_version":"core-v5"},{"registry_id":"core-schema-registry","schema_version":"core-v6"},{"registry_id":"core-schema-registry","schema_version":"core-v7"},{"regist