INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('fsa-lfp', 'd341de0c1c6f8c2d75fef38f1ec413180fc6a364a07af0731f9e842269d02dd1', '{"title":"Livestock Forage Disaster Program (LFP)","navigator":"farmer_producer","program_id":"fsa-lfp","requirements":[{"value":["owned","leased","mixed"],"citation":{"excerpt":"Eligible applicants include livestock producers who own or lease grazing land or pastureland in areas affected by qualifying drought or fire.","locator":"html.visible_text: Who Is Eligible","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"operator":"one_of","statement":"Applicant must own or lease grazing land or pastureland in an area affected by qualifying drought or fire.","concept_id":"land_tenure_owned_or_leased","mapping_status":"mapped","requirement_id":"lfp-owns-or-leases-grazing-land","requirement_type":"eligibility","profile_attribute":"land_tenure"},{"value":["drought","fire"],"citation":{"excerpt":"provides financial support to eligible livestock producers who experience grazing losses due to qualifying drought or fire conditions.","locator":"html.visible_text: What It Is","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"operator":"one_of","statement":"Grazing losses must be due to qualifying drought or fire conditions.","concept_id":"loss_type_drought_or_fire","mapping_status":"mapped","requirement_id":"lfp-loss-cause-drought-or-fire","requirement_type":"eligibility","profile_attribute":"loss_type"},{"citation":{"excerpt":"D2 (Severe Drought) for at least four consecutive weeks – One monthly payment","locator":"html.visible_text: Payment Rates","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"statement":"Grazing land must be in a county rated D2 (Severe Drought) or worse by the U.S. Drought Monitor during the normal grazing period.","concept_id":"county_drought_monitor_rating","mapping_status":"partial","requirement_id":"lfp-drought-monitor-threshold","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for county drought rating or duration"},{"citation":{"excerpt":"Eligible Livestock: Includes beef cattle, dairy cattle, buffalo, bison, beefalo, water buffalo, equine, goats, sheep, alpacas, ostriches, emus, deer, elk, caribou/reindeer, and llamas maintained for commercial use as part of a farming operation.","locator":"html.visible_text: Program Features","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"statement":"Livestock must be an eligible kind maintained for commercial use as part of a farming operation.","concept_id":"eligible_livestock_kind","mapping_status":"partial","requirement_id":"lfp-eligible-livestock-kinds","requirement_type":"eligibility","unresolved_reason":"profile commodities is free text; eligible-kind list matching is not supported by the contract"},{"citation":{"excerpt":"Producers must provide verifiable documentation of grazing losses and meet all program requirements.","locator":"html.visible_text: Who Is Eligible","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"statement":"Producers must provide verifiable documentation of grazing losses.","mapping_status":"not_mapped","requirement_id":"lfp-verifiable-loss-documentation","requirement_type":"application","unresolved_reason":"documentation evidence is not a profile fact"}],"compiled_rules":[{"citation":{"excerpt":"Eligible applicants include livestock producers who own or lease grazing land or pastureland in areas affected by qualifying drought or fire.","locator":"html.visible_text: Who Is Eligible","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"criterion":{"value":["owned","leased","mixed"],"operator":"one_of","attribute":"core.farm_business.land_tenure","source_id":"public-domain.gov","criterion_id":"lfp-owns-or-leases-grazing-land","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"Applicant must own or lease grazing land or pastureland in an area affected by qualifying drought or fire.","applicability":null,"requirement_id":"lfp-owns-or-leases-grazing-land","threshold_basis":null},{"citation":{"excerpt":"provides financial support to eligible livestock producers who experience grazing losses due to qualifying drought or fire conditions.","locator":"html.visible_text: What It Is","source_id":"public-domain.gov","source_url":"https://www.fsa.usda.gov/resources/disaster-recovery/livestock-forage-disaster-program-lfp","retrieved_at":"2026-11-18T02:41:27.567461Z","source_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_record_id":"source-page-2397219d3cf522f5e440","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"},"criterion":{"value":["drought","fire"],"operator":"one_of","attribute":"core.farm_business.loss_type","source_id":"public-domain.gov","criterion_id":"lfp-loss-cause-drought-or-fire","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"Grazing losses must be due to qualifying drought or fire conditions.","applicability":null,"requirement_id":