recovery/livestock-forage-disaster-program-lfp","title":"Livestock Forage Disaster Program (LFP) | Farm Service Agency","agency":"USDA FSA","source_id":"public-domain.gov","source_type":"public_source","jurisdiction":{"level":"federal","country_code":"US"},"retrieved_at":"2026-11-18T02:41:27.567461Z","approval_status":"unverified","authority_class":"unverified","observed_at_utc":"2026-11-18T02:41:27.567461+00:00","contract_version":"source-reference-v1","publisher_version":"sha256:4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_content_sha256":"4765de2d389587850369adbc222afa120bb9df824dba373e9dd543dc14b03252","source_verification_status":"unverified","source_visible_text_sha256":"a682472d7aa7ff59f8f74f55a854f7da3fa68c778fb2bfbfeb5f86f1e6c19eb0"}],"criteria_package_id":"criteria-1dd97758c4b7f68939e855cb47126451","profile_schema_refs":[{"registry_id":"core-schema-registry","schema_version":"core-v8"}]}'::jsonb, '2026-11-18T02:42:49.061776+00:00', 'eligibility') ON CONFLICT DO NOTHING;
INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('kansas-snap-residency', '8eb7c7d9482b6c467ac49fd85b75f0425784d5ccac239665c9dad8cff4847b85', '{"title":"Kansas Food Assistance residency guidance","navigator":"low_income_assistance","program_id":"kansas-snap-residency","requirements":[{"value":"KS","citation":{"excerpt":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","locator":"runtime-mapper:1","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"operator":"eq","statement":"For Food Assistance, individuals must live in the state of Kansas.","concept_id":"state_residency","mapping_status":"mapped","requirement_id":"fa-live-in-state","requirement_type":"eligibility","profile_attribute":"state_code"},{"citation":{"excerpt":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","locator":"runtime-mapper:2","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Food Assistance applicants are not required to have the intent to permanently reside in Kansas.","mapping_status":"context_only","requirement_id":"fa-no-intent-required","requirement_type":"context"},{"citation":{"excerpt":"Individuals in the state solely for vacation purposes are not considered residents.","locator":"runtime-mapper:3","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Individuals in the state solely for vacation purposes are not considered residents for Food Assistance.","concept_id":"vacation_only_presence","mapping_status":"partial","requirement_id":"fa-vacation-not-resident","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for ''solely in state for vacation purposes''"},{"citation":{"excerpt":"A fixed living or mailing address is not required. Homeless individuals are considered residents.","locator":"runtime-mapper:4","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"A fixed living or mailing address is not required for Food Assistance residency.","mapping_status":"context_only","requirement_id":"fa-no-fixed-address-required","requirement_type":"context"},{"value":"homeless","citation":{"excerpt":"Homeless individuals are considered residents.","locator":"runtime-mapper:5","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"operator":"eq","statement":"Homeless individuals are considered residents for Food Assistance purposes.","concept_id":"homeless_residency_eligibility","mapping_status":"mapped","requirement_id":"fa-homeless-considered-resident","requirement_type":"eligibility","profile_attribute":"housing_status"},{"citation":{"excerpt":"Temporary absence from the state exists when a visit for a period of less than one calendar month is made out of the state and the intent is to return.","locator":"runtime-mapper:6","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Temporary absence from Kansas (a visit of less than one calendar month out of state with intent to return) does not interrupt residency.","mapping_status":"context_only","requirement_id":"fa-temporary-absence-rule","requirement_type":"context"},{"citation":{"excerpt":"If the absence is to cover a full calendar month, the individual(s) should be removed from the household.","locator":"runtime-mapper:7","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"If a household member''s absence covers a full calendar month, the individual should be removed from the household.","mapping_status":"context_only","requirement_id":"fa-full-month-absence-removal","requirement_type":"context"},{"citation":{"excerpt":"When a client notifies the agency of a move to another state with the intent to reside there, the client must be informed in writing that assistance is being discontinued giving timely and adequate notice.","locator":"runtime-mapper:8","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"When a client notifies the agency of a move to another state with intent to reside there, assistance must be discontinued with written notice.","mapping_status":"context_only","requirement_id":"fa-move-to-another-state-discontinuation","requirement_type":"context"},{"citation":{"excerpt":"However for cash and food assistance purposes, benefits cannot be provided in any month in which the client has received such benefits in another state.","locator":"runtime-mapper:9","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Food assistance benefits cannot be provided in any month in which the client has received such benefits in another state.","concept_id":"duplicate_benefits_prohibition","mapping_status":"partial","requirement_id":"fa-no-duplicate-benefits-other-state","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for benefits received in another state in the same month"},{"citation":{"excerpt":"no individual may participate as a member of more than one household, unless an individual is a resident of a shelter for battered persons and children as defined in 2543 and was a member of a household containing the person who has abused her","locator":"runtime-mapper:10","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"No individual may participate in Food Assistance as a member of more than one household (with limited exceptions for battered persons shelters).","mapping_status":"context_only","requirement_id":"fa-no-dual-household-participation","requirement_type":"context"},{"citation":{"excerpt":"no individual may participate in the Food Assistance Program and the Food Distribution Program on Indian Reservations (FDPIR) in the same month.","locator":"runtime-mapper:11","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"No individual may participate in the Food Assistance Program and the Food Distribution Program on Indian Reservations (FDPIR) in the same month.","mapping_status":"context_only","requirement_id":"fa-no-fdpir-same-month","requirement_type":"context"},{"citation":{"excerpt":"Persons disqualified from FDPIR for fraud cannot participate in food assistance until the disqualification period has expired.","locator":"runtime-mapper:12","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Persons disqualified from FDPIR for fraud cannot participate in food assistance until the disqualification period has expired.","concept_id":"fdpir_fraud_disqualification","mapping_status":"partial","requirement_id":"fa-fdpir-fraud-disqualification","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for FDPIR fraud disqualification status"},{"citation":{"excerpt":"Applicants or recipients 18 and older:\n\nSocial Security number verified by automated match with the Social Security Administration (KEESM 2131 #1)\n\nResidency (KEESM 1322.1 #4)\n\nIdentity (KEESM 1322.1 #5)","locator":"runtime-mapper:13","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Prior to a NAC query, applicants or recipients 18 and older must have their Social Security number verified by automated match with the Social Security Administration.","mapping_status":"not_mapped","requirement_id":"nac-ssn-verification-adults","requirement_type":"application"},{"citation":{"excerpt":"Applicants or recipients under 18:\n\nSocial Security number verified by automated match with the Social Security Administration (KEESM 2131 #1)\n\nResidency (KEESM 1322.1 #4)","locator":"runtime-mapper:14","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"statement":"Prior to a NAC query, applicants or recipients under 18 must have their Social Security number verified by automated match with the Social Security Administration.","mapping_status":"not_mapped","requirement_id":"nac-ssn-verification-minors","requirement_type":"application"}],"compiled_rules":[{"citation":{"excerpt":"For the Food Assistance Program, Individuals must live in the state, but are not required to have the intent to permanently reside in the state in which they make application.","locator":"runtime-mapper:1","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"criterion":{"value":"KS","operator":"eq","attribute":"core.geography.state_code","source_id":"public-domain.gov","criterion_id":"fa-live-in-state","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"For Food Assistance, individuals must live in the state of Kansas.","applicability":null,"requirement_id":"fa-live-in-state","threshold_basis":null},{"citation":{"excerpt":"Homeless individuals are considered residents.","locator":"runtime-mapper:5","source_id":"public-domain.gov","source_url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","retrieved_at":"2026-11-10T23:44:46.182588Z","source_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_record_id":"source-page-9aae76b531c027e4c297","source_content_sha256":"2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112","source_visible_text_sha256":"7ec35594e0b8c25e1cbb0e24ef4fca788be832af7e2b3bf48e0097c74fd22aff"},"criterion":{"value":"homeless","operator":"eq","attribute":"core.household.housing_status","source_id":"public-domain.gov","criterion_id":"fa-homeless-considered-resident","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"Homeless individuals are considered residents for Food Assistance purposes.","applicability":null,"requirement_id":"fa-homeless-considered-resident","threshold_basis":null}],"program_record":{"title":"Kansas Food Assistance residency guidance","details":[],"sources":[{"url":"https://content.dcf.ks.gov/ees/KEESM/current/keesm2150.htm","title":"2150 Residence — Kansas Economic and Employment Services Manual","agency":"Kansas Department for Children and Families","source_id":"public-domain.gov","source_type":"public_source","jurisdiction":{"level":"state","state_code":"KS","county_name":null,"country_code":"US"},"retrieved_at":"2026-11-10T23:44:46.182588Z","effective_date":null,"approval_status":"unverified","contract_version":"source-reference-v1","publisher_version":"sha256:2506fc5fa725fa31d81e14d601acc9dbc30113e3f877f79c018bd39e15e5b112"}],"criteria":[{"value":"KS","operator":"eq","attribute":"core.geography.state_code","source_id":"public-domain.gov","criterion_id":"fa-live-in-state","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},{"value":"homeless","operator":"eq","attribute":"core.household.housing_status","source_id":"public-domain.gov","criterion_id":"fa-homeless-considered-resident","logic_group_id":null,"context_attribute":null,"logic_group_operator":null}],"navigator":"low_income_assistance","program_id":"kansas-snap-residency","data_origin":"public_source","description":"Kansas DCF states Food Assistance applicants must live in Kansas. This source supports residency routing only; it does not establish complete SNAP eligibility.","jurisdiction":{"level":"state","state_code":"KS","county_name":null,"country_code":"US"},"catalog_version":"request-scoped","contract_version":"eligibility-program-v1","source_limitations":["Only the source-backed Kansas Food Assistance residency condition is mapped. This is not a complete SNAP eligibility ruleset.","Source also states vacation-only presence is not residency, 