INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('medicare-extra-help', '3f99f1122918801168b1e7762153829f6f2f4b199d83625bb64756caa5783c84', '{"title":"Extra Help (Medicare Part D Low-Income Subsidy)","navigator":"low_income_assistance","program_id":"medicare-extra-help","requirements":[{"unit":"USD/year","value":{"1":23940,"2":32460},"citation":{"excerpt":"Individual | $23,940 | $18,090\n\nMarried couple | $32,460 | $36,100","locator":"runtime-mapper:1","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"operator":"lte_by","statement":"Individual applicants must have annual income at or below $23,940 (2026 limit).","concept_id":"income_within_limit","mapping_status":"mapped","requirement_id":"income-limit-individual","threshold_basis":"2026 program limits","requirement_type":"eligibility","context_attribute":"household_size","profile_attribute":"annual_household_income_usd"},{"citation":{"excerpt":"Individual | $23,940 | $18,090\n\nMarried couple | $32,460 | $36,100","locator":"runtime-mapper:2","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"Individual applicants must have resources at or below $18,090; married couples at or below $36,100 (2026 limits).","mapping_status":"partial","requirement_id":"resource-limit-individual","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for household resources/assets"},{"citation":{"excerpt":"Extra Help isn''t available in Puerto Rico, the U.S. Virgin Islands, Guam, the Northern Mariana Islands, or American Samoa.","locator":"runtime-mapper:3","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"Extra Help is not available in Puerto Rico, the U.S. Virgin Islands, Guam, the Northern Mariana Islands, or American Samoa.","concept_id":"geographic_eligibility","mapping_status":"partial","requirement_id":"geographic-exclusion","requirement_type":"eligibility","profile_attribute":"state_code","unresolved_reason":"Excluded territories are not standard US state codes; operator and value table cannot be reliably bound with available profile_attribute values for territories."},{"citation":{"excerpt":"You''ll get Extra Help automatically if you get:\n\n- Full-benefit Medicaid coverage","locator":"runtime-mapper:4","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"You qualify automatically for Extra Help if you get full-benefit Medicaid coverage.","concept_id":"automatic_qualification_medicaid","mapping_status":"partial","requirement_id":"automatic-qualification-medicaid","requirement_type":"eligibility","profile_attribute":"health_coverage_status","unresolved_reason":"health_coverage_status is a string enum; specific value for full-benefit Medicaid is not defined in profile schema."},{"citation":{"excerpt":"- Help from your state paying your Part B premiums (from a Medicare Savings Program )","locator":"runtime-mapper:5","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"You qualify automatically for Extra Help if your state helps pay your Part B premiums through a Medicare Savings Program.","mapping_status":"not_mapped","requirement_id":"automatic-qualification-msp","requirement_type":"eligibility","unresolved_reason":"No profile attribute for Medicare Savings Program participation."},{"citation":{"excerpt":"- Supplemental Security Income (SSI) payments from Social Security","locator":"runtime-mapper:6","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"You qualify automatically for Extra Help if you receive Supplemental Security Income (SSI) payments from Social Security.","mapping_status":"not_mapped","requirement_id":"automatic-qualification-ssi","requirement_type":"eligibility","unresolved_reason":"No profile attribute for SSI receipt."},{"citation":{"excerpt":"\"Extra Help\" is a Medicare program to help people with limited income and resources pay Medicare drug coverage (Part D) premiums, deductibles, coinsurance, and other costs.","locator":"runtime-mapper:7","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8b8a6c6bd88eb1a997f87d97800f4a30f73d"},"statement":"Extra Help is a Medicare program to help people with limited income and resources pay Medicare drug coverage (Part D) premiums, deductibles, coinsurance, and other costs.","mapping_status":"context_only","requirement_id":"program-purpose","requirement_type":"context"}],"compiled_rules":[{"citation":{"excerpt":"Individual | $23,940 | $18,090\n\nMarried couple | $32,460 | $36,100","locator":"runtime-mapper:1","source_id":"cms.medicare-extra-help","source_url":"https://www.medicare.gov/basics/costs/help/drug-costs","retrieved_at":"2026-11-11T02:25:01.231050Z","source_version":"sha256:73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_record_id":"source-page-213b3b5e9ddd094131c8","source_content_sha256":"73d1e8dca4f737aaedc3c56bf47540b451ca12cf6935edc1452aa1f7c330bf4e","source_visible_text_sha256":"ad590dea33555421faeecec08cde8