INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('missouri-child-care-subsidy', 'd58fd56647bcaf61dcd43348f10d7d7c7df41b3ede772ed29c15513363463348', '{"title":"Child Care Subsidy Information for Families | Missouri Department of Elementary and Secondary Education","navigator":"low_income_assistance","program_id":"missouri-child-care-subsidy","requirements":[{"value":"MO","citation":{"excerpt":"Your child moves out of Missouri.","locator":"runtime-mapper:1","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","retrieved_at":"2026-11-10T15:30:23.361520Z","source_version":"sha256:f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_record_id":"source-page-37a0c7616c5aaddbbe10","source_content_sha256":"f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6"},"operator":"eq","statement":"Child must reside in Missouri (child must not move out of Missouri).","concept_id":"state_residency","mapping_status":"mapped","requirement_id":"state-residency","requirement_type":"eligibility","profile_attribute":"state_code"},{"citation":{"excerpt":"Have a child birth to age 13, or a child with special needs or receiving protective services","locator":"runtime-mapper:2","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","retrieved_at":"2026-11-10T15:30:23.361520Z","source_version":"sha256:f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_record_id":"source-page-37a0c7616c5aaddbbe10","source_content_sha256":"f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6"},"statement":"Family must have a child birth to age 13, or a child with special needs or receiving protective services.","concept_id":"child_age","mapping_status":"partial","requirement_id":"child-age","requirement_type":"eligibility","profile_attribute":"household_children","unresolved_reason":"Profile fields do not include a child age attribute; household_children only counts children, not their ages."},{"value":true,"citation":{"excerpt":"Need child care to work, search for work, participate in job training, or attend school","locator":"runtime-mapper:3","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","retrieved_at":"2026-11-10T15:30:23.361520Z","source_version":"sha256:f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_record_id":"source-page-37a0c7616c5aaddbbe10","source_content_sha256":"f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6"},"operator":"eq","statement":"Family must need child care to work, search for work, participate in job training, or attend school.","concept_id":"childcare_need","mapping_status":"mapped","requirement_id":"qualifying-activity","requirement_type":"eligibility","profile_attribute":"childcare_need"},{"unit":"USD/year","citation":{"excerpt":"Be at or below 150% of the federal poverty level","locator":"runtime-mapper:4","source_id":"missouri.dese.child-care-subsidy","source_url":"https://dese.mo.gov/childhood/child-care-subsidy/families","retrieved_at":"2026-11-10T15:30:23.361520Z","source_version":"sha256:f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_record_id":"source-page-37a0c7616c5aaddbbe10","source_content_sha256":"f74d6a6febe258ebfa41d59eb3cedf843ab0b710e949d7f48a366617e4819a12","source_visible_text_sha256":"2c2d61a566cff87d8af847a7bdcd646ec2725fecf64ed2d074d2ae90306978e6"},"statement":"Family must be at or below 150% of the federal poverty level.","concept_id":"