INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('missouri-snap', '00046811887a909c907fb60df329bab0bdb9e8d2ee4b6fd2ccfeab52dc2dde96', '{"title":"Missouri SNAP application guidance","navigator":"low_income_assistance","program_id":"missouri-snap","requirements":[{"value":"MO","citation":{"excerpt":"Live in Missouri","locator":"html.visible_text: Who is eligible?","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-18T02:44:36.822738Z","source_version":"sha256:011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"operator":"eq","statement":"Applicant must live in Missouri.","concept_id":"state_residency","mapping_status":"mapped","requirement_id":"mo-snap-lives-in-missouri","requirement_type":"eligibility","profile_attribute":"state_code"},{"citation":{"excerpt":"Have (or agree to apply for) a Social Security Number for all members of your household","locator":"html.visible_text: Who is eligible?","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-18T02:44:36.822738Z","source_version":"sha256:011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"All household members have, or agree to apply for, a Social Security Number.","concept_id":"household_ssn_status","mapping_status":"partial","requirement_id":"mo-snap-ssn-all-members","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for household Social Security number status"},{"citation":{"excerpt":"Do not make more than the current income limit","locator":"html.visible_text: Who is eligible?","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-18T02:44:36.822738Z","source_version":"sha256:011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Household income must not exceed the current income limit.","mapping_status":"not_mapped","requirement_id":"mo-snap-income-limit","requirement_type":"eligibility","unresolved_reason":"threshold not stated in source"},{"citation":{"excerpt":"Do not own more than $3,000 in resources ($4,750 if at least one member of your household is over the age of 60 or disabled)","locator":"html.visible_text: Who is eligible?","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-18T02:44:36.822738Z","source_version":"sha256:011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"011f371a49bbbcb0010a9777153837ee253cd18ae1875edbc6688539f39d9088","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Household resources must not exceed $3,000 ($4,750 if a member is over 60 or disabled).","concept_id":"household_countable_resources","mapping_status":"partial","requirement_id":"mo-snap-resource-limit","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for countable resources in the household profile"}],"compiled_rules":[{"citation":{"excerpt