INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('program-ref-155ae8665401542dd1506c10624fc8d6', '138c6fba8079422dca46d9c67a073950f967c6bc2aa14fb0b63887704405e130', '{"title":"Missouri SNAP application guidance","navigator":"low_income_assistance","program_id":"program-ref-155ae8665401542dd1506c10624fc8d6","requirements":[{"value":"MO","citation":{"excerpt":"Live in Missouri","locator":"runtime-mapper:1","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"operator":"eq","statement":"Applicant must live in Missouri.","concept_id":"state_residency","mapping_status":"mapped","requirement_id":"state-residency-mo","requirement_type":"eligibility","profile_attribute":"state_code"},{"unit":"USD/month","citation":{"excerpt":"Do not make more than the current income limit","locator":"runtime-mapper:2","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Household must not make more than the current income limit.","concept_id":"gross_income_limit","mapping_status":"partial","requirement_id":"income-limit","requirement_type":"eligibility","profile_attribute":"monthly_gross_income_usd","unresolved_reason":"Income limit table not published on this page; exact thresholds not available."},{"citation":{"excerpt":"Do not own more than $3,000 in resources ($4,750 if at least one member of your household is over the age of 60 or disabled)","locator":"runtime-mapper:3","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Household must not own more than $3,000 in countable resources.","mapping_status":"not_mapped","requirement_id":"resource-limit-standard","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for household liquid resources / asset value"},{"citation":{"excerpt":"$4,750 if at least one member of your household is over the age of 60 or disabled","locator":"runtime-mapper:4","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"If at least one household member is over 60 or disabled, the resource limit is $4,750.","mapping_status":"not_mapped","requirement_id":"resource-limit-elderly-disabled","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for household liquid resources / asset value"},{"citation":{"excerpt":"Have (or agree to apply for) a Social Security Number for all members of your household","locator":"runtime-mapper:5","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"All household members must have (or agree to apply for) a Social Security Number.","mapping_status":"not_mapped","requirement_id":"social-security-number","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for Social Security Number status"},{"citation":{"excerpt":"If any member of your household was convicted after August 22, 1996 of a felony or any crime related to illegal possession, use, or distribution of a controlled substance, or is a fleeing felon and is in violation of a condition of their probation or parole, they may not be able to get SNAP benefits for themselves.","locator":"runtime-mapper:6","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Household members convicted after August 22, 1996 of a felony or drug-related crime, or fleeing felons violating probation/parole conditions, may not be eligible.","mapping_status":"not_mapped","requirement_id":"felony-drug-conviction-restriction","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for felony conviction or fleeing felon status"},{"citation":{"excerpt":"The Supplemental Nutrition Assistance Program (SNAP) offers a monthly benefit to help you buy food and food products, such as seeds and plants to grow food. This monthly benefit is loaded to an Electronic Benefit Transfer (EBT) card and cannot be withdrawn as cash.","locator":"runtime-mapper:7","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"SNAP provides a monthly benefit loaded to an EBT card to help buy food and food products.","mapping_status":"context_only","requirement_id":"food-assistance-program-context","requirement_type":"context"},{"citation":{"excerpt":"Your monthly benefit amount will depend on your income and the size of your household .","locator":"runtime-mapper:8","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"statement":"Monthly benefit amount depends on income and household size.","mapping_status":"context_only","requirement_id":"benefit-amount-context","requirement_type":"context"}],"compiled_rules":[{"citation":{"excerpt":"Live in Missouri","locator":"runtime-mapper:1","source_id":"missouri.dss.snap","source_url":"https://dss.mo.gov/food-assistance/apply-for-snap","retrieved_at":"2026-11-08T22:26:53.297506Z","source_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_record_id":"source-page-562476b2361dce3f4411","source_content_sha256":"dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9","source_visible_text_sha256":"8fa43daa0914585bc822092a0a757347d95a9a4cad4239af8cd15b6d0e5d7884"},"criterion":{"value":"MO","operator":"eq","attribute":"core.geography.state_code","source_id":"missouri.dss.snap","criterion_id":"state-residency-mo","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"Applicant must live in Missouri.","applicability":null,"requirement_id":"state-residency-mo","threshold_basis":null}],"program_record":{"title":"Missouri SNAP application guidance","details":[],"sources":[{"url":"https://dss.mo.gov/food-assistance/apply-for-snap","title":"Apply for SNAP | Missouri Department of Social Services","agency":"Missouri Department of Social Services","source_id":"missouri.dss.snap","source_type":"public_source","jurisdiction":{"level":"state","state_code":"MO","county_name":null,"country_code":"US"},"retrieved_at":"2026-11-08T22:26:53.297506Z","effective_date":null,"approval_status":"approved","contract_version":"source-reference-v1","publisher_version":"sha256:dc9d6d980d64eb600d29da5f1675c3e8e5b8b6bc15c51985462f904f66b47fd9"}],"criteria":[{"value":"MO","operator":"eq","attribute":"core.geography.state_code","source_id":"missouri.dss.snap","criterion_id":"state-residency-mo","logic_group_id":null,"context_attribute":null,"logic_group_operator":null}],"navigator":"low_income_assistance","program_id":"program-ref-155ae8665401542dd1506c10624fc8d6","data_origin":"public_source","description":"Missouri DSS official SNAP page; this slice maps Missouri residency only.","jurisdiction":{"level":"state","state_code"