an the annual income limit for your household size","locator":"runtime-mapper:5","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Household income must be less than the annual income limit for the household size.","concept_id":"income_limit_by_household_size","mapping_status":"partial","requirement_id":"families-income-limit","requirement_type":"eligibility","context_attribute":"household_size","profile_attribute":"annual_household_income_usd","unresolved_reason":"specific income limit dollar amounts not stated on this page"},{"citation":{"excerpt":"Cooperate with Child Support for medical support","locator":"runtime-mapper:6","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Applicant must cooperate with Child Support for medical support.","mapping_status":"partial","requirement_id":"families-child-support-cooperation","requirement_type":"eligibility","unresolved_reason":"no registered profile attribute for child support cooperation"},{"citation":{"excerpt":"NOTE : The child will also be covered.","locator":"runtime-mapper:7","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"The child of the applicant will also be covered under this program.","mapping_status":"context_only","requirement_id":"families-child-also-covered","requirement_type":"context"},{"citation":{"excerpt":"You must be age 19-64 and:","locator":"runtime-mapper:8","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Expansion Adults must be age 19-64.","mapping_status":"context_only","requirement_id":"expansion-adults-age","requirement_type":"context"},{"citation":{"excerpt":"You must be 65 or older and:","locator":"runtime-mapper:9","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Seniors coverage requires applicant to be 65 or older.","mapping_status":"context_only","requirement_id":"seniors-age","requirement_type":"context"},{"citation":{"excerpt":"The child must 18 or under and:","locator":"runtime-mapper:10","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Children & Youth coverage requires the child to be 18 or under.","mapping_status":"context_only","requirement_id":"children-youth-age","requirement_type":"context"},{"citation":{"excerpt":"Depending on your age, health, and individual needs, you may be eligible for a certain type of MO HealthNet (Missouri Medicaid) Coverage.","locator":"runtime-mapper:11","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-requirements-mo-healthnet-coverage","retrieved_at":"2026-11-12T01:09:52.036517Z","source_version":"sha256:84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_record_id":"source-page-4250af5edc6ab643bc26","source_content_sha256":"84de6b0552d3290f943829c5e32cd0abe0acbf9dff44e9634e253a0c8d54c873","source_visible_text_sha256":"69d228c33662b3cdb113360673f460d1836ae919ceb5fe857e86d961203917fb"},"statement":"Eligibility for MO HealthNet depends on age, health, and individual needs, and there are multiple coverage types.","mapping_status":"context_only","requirement_id":"program-scope-coverage-types","requirement_type":"context"}],"compiled_rules":[{"citation":{"excerpt":"Live in Missouri and be a United States Citizen (or qualified non-citizen)","locator":"runtime-mapper:2","source_id":"public-domain.gov","source_url":"https://dss.mo.gov/eligibility-req