INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('usda-csfp', '1786a04d94badde26253e0b7acdfb37d78b97bf6d7bd0372a04f497f08badd7b', '{"title":"Commodity Supplemental Food Program (CSFP)","navigator":"senior_caregiver","program_id":"usda-csfp","requirements":[{"value":["60_64","65_74","75_plus","65_plus"],"citation":{"excerpt":"The Commodity Supplemental Food Program (CSFP) is designed to improve the health of people with low-income who are at least 60 years of age, by supplementing their diets with nutritious USDA Foods.","locator":"USDA FNS CSFP Factsheet","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/csfp/factsheet","retrieved_at":"2026-11-10T20:09:58.992129Z","source_version":"sha256:3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_record_id":"source-page-08958e46b58e1682534e","source_content_sha256":"3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_visible_text_sha256":"18716f718db727b3e11c7496601293961724bd9135a799c704391fe3d4f8cf68"},"operator":"one_of","statement":"The Commodity Supplemental Food Program (CSFP) is designed to improve the health of people with low-income who are at least 60 years of age, by supplementing their diets with nutritious USDA Foods.","concept_id":"csfp.minimum_age","mapping_status":"mapped","requirement_id":"csfp-minimum-age-60","requirement_type":"eligibility","profile_attribute":"core.person.age_band"},{"citation":{"excerpt":"Each state agency and ITO sets income limits for participants which must be at or below 150 percent of the Federal Poverty Income Guidelines. State agencies and ITOs may establish local residency requirements based on designated service areas (but may not require a minimum period of residency). State agencies and ITOs may also require that participants be at nutritional risk, as determined by a physician or local agency staff.","locator":"USDA FNS CSFP Factsheet","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/csfp/factsheet","retrieved_at":"2026-11-10T20:09:58.992129Z","source_version":"sha256:3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_record_id":"source-page-08958e46b58e1682534e","source_content_sha256":"3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_visible_text_sha256":"18716f718db727b3e11c7496601293961724bd9135a799c704391fe3d4f8cf68"},"statement":"Each state agency and ITO sets income limits for participants which must be at or below 150 percent of the Federal Poverty Income Guidelines. State agencies and ITOs may establish local residency requirements based on designated service areas (but may not require a minimum period of residency). State agencies and ITOs may also require that participants be at nutritional risk, as determined by a physician or local agency staff.","mapping_status":"partial","requirement_id":"csfp-state-income-limit","requirement_type":"eligibility","unresolved_reason":"States/ITOs set program-specific income limits at or below the federal guideline; there is no nationally uniform cutoff in the profile. Keep income unknown pending a jurisdiction-specific table and income-basis mapping."},{"citation":{"excerpt":"State agencies and ITOs may establish local residency requirements based on designated service areas (but may not require a minimum period of residency). State agencies and ITOs may also require that participants be at nutritional risk, as determined by a physician or local agency staff.","locator":"USDA FNS CSFP Factsheet","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/csfp/factsheet","retrieved_at":"2026-11-10T20:09:58.992129Z","source_version":"sha256:3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_record_id":"source-page-08958e46b58e1682534e","source_content_sha256":"3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_visible_text_sha256":"18716f718db727b3e11c7496601293961724bd9135a799c704391fe3d4f8cf68"},"statement":"State agencies and ITOs may establish local residency requirements based on designated service areas (but may not require a minimum period of residency). State agencies and ITOs may also require that participants be at nutritional risk, as determined by a physician or local agency staff.","mapping_status":"partial","requirement_id":"csfp-residency-service-area","requirement_type":"eligibility","unresolved_reason":"Optional local service-area requirements require a state/ITO-specific agency lookup not represented by current profile facts."}],"compiled_rules":[{"citation":{"excerpt":"The Commodity Supplemental Food Program (CSFP) is designed to improve the health of people with low-income who are at least 60 years of age, by supplementing their diets with nutritious USDA Foods.","locator":"USDA FNS CSFP Factsheet","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/csfp/factsheet","retrieved_at":"2026-11-10T20:09:58.992129Z","source_version":"sha256:3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_record_id":"source-page-08958e46b58e1682534e","source_content_sha256":"3e8320ea27d85065b98e77da80920b8a2f943e4627d065da11c84ff05b50d67c","source_visible_text_sha256":"18716f718db727b3e11c7496601293961724bd9135a799c704391fe3d4f8cf68"},"criterion":{"value":["60_64","65_74","75_plus","65_plus"],"operator":"one_of","attribute":"core.person.age_band","source_id":"public-domain.us","criterion_id":"csfp-minimum-age-60","logic_group_id":null,"context_attribute":null,"logic_group_operator":null},"statement":"The Commodity Supplemental Food Program (CSFP) is designed to improve the health of people with low-income who are at least 60 years of age, by supplementing their diets with nutritious USDA Foods.","applicability":null,"requirement_id":"csfp-minimum-age-60","threshold_basis":null}],"program_record":{"title":"Commodity Supplemental Food Prog