INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('usda-nrcs-eqip', '8fe50222c973932e749cbb7a1e8f751425725b737cfd12c7d2dd67557a26459f', '{"title":"Environmental Quality Incentives Program (EQIP) partial land-control screen","navigator":"farmer_producer","program_id":"usda-nrcs-eqip","requirements":[{"value":true,"citation":{"excerpt":"Farm records must be established or updated with the Farm Service Agency for both applicants and land; farm records must indicate the applicant controls or owns eligible land.","locator":"Preparing Your Application > Farm records must indicate the applicant","source_id":"usda.nrcs.eqip","source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for-environmental-quality","retrieved_at":"2026-11-11T02:18:29.994157Z","source_version":"sha256:56d578eaab295f94b19b62788168ab7ef0fe564650df01a5479b6e633dfaed5a","source_record_id":"source-page-752e51a67ff85a64cdc5","source_content_sha256":"56d578eaab295f94b19b62788168ab7ef0fe564650df01a5479b6e633dfaed5a","source_visible_text_sha256":"e0405c6bb30e19eaa6aa4f2f9107b3a190423ce8ed57eea588b8cafc31e8a83d"},"operator":"eq","statement":"Farm records must indicate the applicant controls or owns eligible land.","concept_id":"eqip.fsa_records.eligible_land_control","mapping_status":"mapped","requirement_id":"eqip-fsa-records-eligible-land-control","requirement_type":"eligibility","profile_attribute":"nrcs.eqip.fsa_records_confirm_eligible_land_control"}],"compiled_rules":[{"citation":{"excerpt":"Farm records must be established or updated with the Farm Service Agency for both applicants and land; farm records must indicate the applicant controls or owns eligible land.","locator":"Preparing Your Application > Farm records must indicate the applicant","source_id":"usda.nrcs.eqip","source_url":"https://www.nrcs.usda.gov/programs-initiatives/environmental-quality-incentives-program/apply-for