INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('usda-sfmnp', '65cbbb366a5f652c3a615cb2f6c2be5a1273af6769b6c68f202e0e8a7bb44a3b', '{"title":"Senior Farmers Market Nutrition Program (SFMNP)","navigator":"senior_caregiver","program_id":"usda-sfmnp","requirements":[{"value":["60_64","65_74","75_plus","65_plus"],"citation":{"excerpt":"Low-income seniors, generally defined as individuals who are at least 60 years old and who have household incomes of not more than 185% of the federal poverty income guidelines.","locator":"USDA FNS SFMNP program page","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/sfmnp","retrieved_at":"2026-11-10T20:10:34.046040Z","source_version":"sha256:323d3fbe79ebebfeafd81dd6eac18d98127f28933ea64da58f86c33bc4c46c7d","source_record_id":"source-page-60f5255b3ece48384d02","source_content_sha256":"323d3fbe79ebebfeafd81dd6eac18d98127f28933ea64da58f86c33bc4c46c7d","source_visible_text_sha256":"2ae367dc70828955059826ed34e1620f69c21625d7e96a0b8d205b0e392ca9c5"},"operator":"one_of","statement":"Low-income seniors, generally defined as individuals who are at least 60 years old and who have household incomes of not more than 185% of the federal poverty income guidelines.","concept_id":"sfmnp.minimum_age","mapping_status":"mapped","requirement_id":"sfmnp-minimum-age-60","requirement_type":"eligibility","profile_attribute":"core.person.age_band"},{"citation":{"excerpt":"Low-income seniors, generally defined as individuals who are at least 60 years old and who have household incomes of not more than 185% of the federal poverty income guidelines.","locator":"USDA FNS SFMNP program page","source_id":"public-domain.us","source_url":"https://fns-prod.azureedge.us/sfmnp","retrieved_at":"2026-11-10T20:10:34.046040Z","source_version":"sha256:323d3fbe79ebebfeafd81dd6eac18d98127f28933ea64da58f86c33bc4c46c7d","source_record_id":"source-page-60f5255b3ece48384d02","source_cont