INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('va-aid-attendance-housebound', '469fb89e86ccee914f60128b85afed60191095894e0c7f6b45b3880031cbc48d', '{"title":"VA Aid and Attendance and Housebound allowance - mapped criteria","navigator":"senior_caregiver","program_id":"va-aid-attendance-housebound","requirements":[{"value":"receiving","citation":{"excerpt":"You may be eligible for this benefit if you get a VA pension.","locator":"VA Aid and Attendance / Housebound eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"operator":"eq","statement":"The applicant must receive a VA pension.","concept_id":"va-pension-prerequisite","criterion_id":"va-pension-prerequisite","mapping_status":"mapped","requirement_id":"va-pension-prerequisite","requirement_type":"eligibility","profile_attribute":"core.person.va_pension_status"},{"value":true,"citation":{"excerpt":"You need another person to help you perform daily activities, like bathing, feeding, and dressing, or","locator":"VA Aid and Attendance / Housebound eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"operator":"eq","statement":"The applicant needs another person to help with daily activities such as bathing, feeding, or dressing.","concept_id":"aid-attendance-daily-assistance","criterion_id":"aid-attendance-daily-assistance","mapping_status":"mapped","requirement_id":"aid-attendance-daily-assistance","requirement_type":"eligibility","profile_attribute":"core.person.daily_care_need"},{"citation":{"excerpt":"You have to stay in bed—or spend a large portion of the day in bed—because of illness, or","locator":"VA Aid and Attendance eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"The applicant must stay in bed or spend a large portion of the day in bed because of illness.","mapping_status":"not_mapped","requirement_id":"aid-attendance-bed-rest","requirement_type":"eligibility","unresolved_reason":"no_matching_fact_in_active_profile_schema"},{"citation":{"excerpt":"You’re a patient in a nursing home due to the loss of mental or physical abilities related to a disability, or","locator":"VA Aid and Attendance eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"The applicant is a nursing-home patient due to loss of mental or physical abilities related to a disability.","mapping_status":"not_mapped","requirement_id":"aid-attendance-nursing-home","requirement_type":"eligibility","unresolved_reason":"no_matching_fact_in_active_profile_schema"},{"citation":{"excerpt":"Your eyesight is limited (even with glasses or contact lenses you have only 5/200 or less in both eyes; or concentric contraction of the visual field to 5 degrees or less)","locator":"VA Aid and Attendance eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_visible_text_sha256":"1c0a26b37d8555975509207e879060039ccd1df366728c7b4e47f1f54c50beec"},"statement":"The applicant has corrected eyesight of 5/200 or less in both eyes, or visual-field contraction to 5 degrees or less.","mapping_status":"not_mapped","requirement_id":"aid-attendance-visual-impairment","requirement_type":"eligibility","unresolved_reason":"no_matching_fact_in_active_profile_schema"},{"value":true,"citation":{"excerpt":"You may be eligible for this benefit if you get a VA pension and you spend most of your time in your home because of a permanent disability (a disability that doesn’t go away).","locator":"VA Aid and Attendance / Housebound eligibility","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/pension/aid-attendance-housebound/","retrieved_at":"2026-11-10T23:38:03.007894Z","source_version":"sha256:24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b","source_record_id":"source-page-90d0807ee65efbd0abfd","source_content_sha256":"24fe8cc618bc2970984ef1ed9fe44faa18bd4064c28c838971408f79203ec72b"