INSERT INTO mcp_saas.eligibility_criteria_rulesets (program_id, content_sha256, ruleset, created_at, cluster_id) VALUES ('va-pcafc', 'd62045ef6b8ae7b8630801d6f59db64cd5e4863312e3258254e39183e8cdd8a0', '{"title":"VA Program of Comprehensive Assistance for Family Caregivers (PCAFC)","navigator":"senior_caregiver","program_id":"va-pcafc","requirements":[{"value":18,"citation":{"excerpt":"You must be at least 18 years old.","locator":"Eligibility requirements for the family caregiver","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"gte","statement":"The family caregiver must be at least 18 years old.","concept_id":"core.person.caregiver.age_years","criterion_id":"caregiver-age","mapping_status":"mapped","requirement_id":"caregiver-age","requirement_type":"eligibility","profile_attribute":"caregiver_age_years"},{"value":["spouse","son","daughter","parent","stepfamily_member","extended_family_member"],"citation":{"excerpt":"At least 1 of these must be true for you: You''re a spouse, son, daughter, parent, stepfamily member, or extended family member of the Veteran.","locator":"Eligibility requirements for the family caregiver","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"one_of","statement":"The caregiver is a spouse, son, daughter, parent, stepfamily member, or extended family member of the Veteran.","concept_id":"core.person.caregiver.relationship_to_veteran","criterion_id":"caregiver-relationship-or-co-residence","logic_group_id":"caregiver-relationship-or-co-residence","mapping_status":"mapped","requirement_id":"caregiver-qualifying-family-relationship","requirement_type":"eligibility","profile_attribute":"caregiver_relationship_to_veteran","logic_group_operator":"any_of"},{"value":true,"citation":{"excerpt":"You live full time with the Veteran, or you''re willing to live full time with the Veteran if we designate you as a family caregiver.","locator":"Eligibility requirements for the family caregiver","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"eq","statement":"The caregiver lives full time with the Veteran or is willing to live full time with the Veteran if designated.","concept_id":"core.person.caregiver.lives_or_willing_to_live_full_time_with_veteran","criterion_id":"caregiver-relationship-or-co-residence","logic_group_id":"caregiver-relationship-or-co-residence","mapping_status":"mapped","requirement_id":"caregiver-full-time-co-residence","requirement_type":"eligibility","profile_attribute":"caregiver_lives_or_willing_to_live_full_time_with_veteran","logic_group_operator":"any_of"},{"unit":"percent","value":70,"citation":{"excerpt":"The Veteran has a VA disability rating (individual or combined) of 70% or higher.","locator":"Eligibility requirements for the Veteran","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"gte","statement":"The Veteran must have an individual or combined VA disability rating of 70% or higher.","concept_id":"core.person.veteran.service_connected_disability_rating_percent","criterion_id":"veteran-disability-rating","mapping_status":"mapped","requirement_id":"veteran-disability-rating","requirement_type":"eligibility","profile_attribute":"veteran_service_connected_disability_rating_percent"},{"value":"qualifying","citation":{"excerpt":"The Veteran was discharged from the U.S. military or has a date of medical discharge.","locator":"Eligibility requirements for the Veteran","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"eq","statement":"The Veteran must have been discharged from the U.S. military or have a date of medical discharge.","concept_id":"core.person.veteran.service_discharge_status","criterion_id":"veteran-discharge","mapping_status":"mapped","requirement_id":"veteran-discharge","requirement_type":"eligibility","profile_attribute":"veteran_service_discharge_status"},{"unit":"months","value":6,"citation":{"excerpt":"The Veteran needs at least 6 months of continuous, in-person personal care services.","locator":"Eligibility requirements for the Veteran","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_visible_text_sha256":"3bc21f81d545f1df03f75bbdcc6dca85da2c2a1be81672e266761dd8131f00a3"},"operator":"gte","statement":"The Veteran must need at least 6 months of continuous, in-person personal care services.","concept_id":"core.person.veteran.continuous_in_person_care_months","criterion_id":"personal-care-duration","mapping_status":"mapped","requirement_id":"personal-care-duration","requirement_type":"eligibility","profile_attribute":"veteran_continuous_in_person_care_months"},{"value":"enrolled","citation":{"excerpt":"The Veteran needs to be enrolled in VA healthcare.","locator":"Eligibility requirements for the Veteran","source_id":"us.va.public-benefits","source_url":"https://www.va.gov/family-and-caregiver-benefits/health-and-disability/comprehensive-assistance-for-family-caregivers/","retrieved_at":"2026-11-09T16:27:14.765158Z","source_version":"sha256:09376b4c3582b08905b77407f77e9b9672e4a2c4802799e7ed80e96ef921179c","source_record_id":"source-page-3be356e06da8ee188be9","source_content_sha256":"0